WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[72584] = { title = "Setting Your Very Own Net", description = "Want to try out your net? Go to the river mouth to the south of Waking Shores, and find a place where the fish are abundant. There should be a good spot for setting up a net.", objectives = "" }
WordHunterWoW_QuestEN[72585] = { title = "Open Orientation", description = "You have done much for the Dragon Isles, hero. \n\nThere are many who are grateful for your contributions and want to welcome you more wholly into their communities. Go to them and orient yourselves with each group and their specialties. \n\nI think you will find that just as you have much to offer the Dragon Isles, many here have much they wish to offer you in return!", objectives = "" }
WordHunterWoW_QuestEN[72588] = { title = "Primalist Pillagers", description = "I'm startin' tae grasp the basics of Winterpelt, but what I'm pickin' up is grim.\n\nSeems a band of Winterpelt foragers fell afoul o' the nearby Primalists. The winters here are as harsh as any in Dun Morogh, an' the supplies they were gatherin' will be sorely missed.\n\nWhy don't ya see about recoverin' what ye can. With prejudice, if ye don't mind.", objectives = "" }
WordHunterWoW_QuestEN[72589] = { title = "Honor Their Sacrifice", description = "There's nothin' we can do for the foragers the Primalists killed, but we can at least try an' provide some closure tae their kin.\n\nSee if ye can find anythin' of a personal nature on the fallen. I'm sure the Winterpelt will appreciate whatever ye can bring them.", objectives = "" }
WordHunterWoW_QuestEN[72590] = { title = "Ursol's Wisdom", description = "We have strayed from wise Ursol's path, trading focus for obsession and contemplation for fear.\n\nGather cones from the mighty Rustpines. As their roots stretch deep into the earth, take strength from the waters, reach into the winds, and are ripened by fire, they will be a symbol of our renewed commitment to true balance.\n\nTake to the skies on that drake of yours and you should be able to gather enough. The upper branches are the best place to find them.\n\nOffer them to Ursol at his nearby shrine.", objectives = "" }
WordHunterWoW_QuestEN[72591] = { title = "A Debt That Must Be Paid", description = "{name}, I have heard you cultivated good relations with the centaur of the Ohn'ahran Plains. I would like to ask a favor.\n\nBaine left for the plains a few days ago in search of a group of missing tauren. I offered to accompany him, but he insisted on going alone.\n\nThe tauren of Thunder Bluff have a long and bloody history with the centaur of Kalimdor, as does Baine. While the Maruuk centaur are unrelated, I still have my concerns.\n\nYour presence could help smooth tensions. I hope.", objectives = "" }
WordHunterWoW_QuestEN[72592] = { title = "Scars from the Past", description = "A tribe of tauren came to the Dragon Isles led by a close friend of mine, Bovan Windtotem. No one has heard from them since they entered these plains.\n\nIf they have gone missing, then I must find them. Unfortunately, I underestimated the size of this place. \n\nYou have an existing relationship with the centaur. Will you go speak with them and see if they have any information on Bovan or his tribe? \n\nPerhaps they can help narrow down my search.", objectives = "" }
WordHunterWoW_QuestEN[72593] = { title = "A Tomul-tuous Beginning", description = "Since the dragons returned, we've seen an overwhelming number of outsiders passing through the plains. Normally we keep a close eye on our borders, but their sheer numbers, combined with the Nokhud threat, have made it difficult to track them.\n\nOne scout reported a group of outsiders that matched your description traveling along the eastern road. We should start our search there.\n\nAs for your friend, my khan gave me a command. A huffy companion won't stop me from carrying it out.", objectives = "" }
WordHunterWoW_QuestEN[72594] = { title = "Delivering Bad News", description = "As soon as we arrived, Baine was whisked away. Bovan is still missing, so he is speaking to someone named Tagar.\n\nOf course I've been left out here in the cold. It seems they still don't trust me.\n\nIn any case, you should go in and speak with the tauren. Take the items you found and try to identify who they belonged to. At the very least, you can let the families know what we've discovered so far.\n\nBut... be gentle, {name}. For some of them, this may be the worst day of their lives.", objectives = "" }
WordHunterWoW_QuestEN[72595] = { title = "The Search for Bovan Windtotem", description = "According to this survivor, the centaur took them completely by surprise. Bovan led many of the braves against the centaur, hoping to buy time for the others to escape. \n\nHe succeeded, but Bovan and most of the braves have not returned. We must find him, {name}.\n\nI need you to search the surrounding area. If you find survivors, tell them to make their way back here.\n\nIf you find fallen tauren... take something recognizable to bring back to their families.", objectives = "" }
WordHunterWoW_QuestEN[72597] = { title = "Ursoc's Strength", description = "It has been many years since we last offered sacrifices to mighty Ursoc, but we will need his blessing if we are to restore balance among our people.\n\nHis shrine is hidden in the mountains to the east where few would stumble upon it by chance.", objectives = "" }
WordHunterWoW_QuestEN[72598] = { title = "Words of the Winterpelt", description = "The Winterpelt Chief sent word while ye were out that he wanted tae speak with ye again.\n\nAnd, thanks tae all the work ye been puttin' in, we could actually understand the message!\n\nWe're on the cusp o' somethin' great here, {name}. Think of it... The trade routes we could establish! The cultural exchange that could take place! The papers I could publish!\n\nWell? What are ye standin' around for? Go see what he wants!", objectives = "" }
WordHunterWoW_QuestEN[72599] = { title = "Joint Rescue Operation", description = "Tomul says the attacks on the Windtotem were carried out by an enemy clan known as the Nokhud. \n\nJust down this road is their closest outpost, and the most likely location where tauren prisoners would be taken.\n\nThe task is simple--rescue the captives. We do not know how many there are, or how long they have been here, so we must hurry.\n\nI speak from experience when I say centaur do not keep their captives for long.", objectives = "" }
WordHunterWoW_QuestEN[72600] = { title = "A Proper Shikaar Send-Off", description = "We're here to rescue the captive tauren, but I have a personal request.\n\nThe place we are assaulting was once my home. The Nokhud took over after a surprise attack during the civil war.\n\nTake these Shikaar banners. When you kill a Nokhud or one of their allies, plant a banner on their corpse. I want to send a message--if they continue to occupy our home, they will pay in blood.", objectives = "" }
WordHunterWoW_QuestEN[72601] = { title = "Bovan's Last Hope", description = "If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot.\n\nWe still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work.\n\nGo to the Ohn'iri Springs and look for Boku. I'm sure he will help us.\n\nBaine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.", objectives = "" }
WordHunterWoW_QuestEN[72602] = { title = "Optimistic Mystic", description = "I'm sure I can find this Bovan Windtotem--but I will need a few items from you.\n\nFirst, I need a selection of flowers that grow at the base of the springs. They have the specific properties we are looking for.\n\nNext, I require the heart of a salamanther. A stronger heart will better our chances--look for the strongest you can find!\n\nI can gather the rest of the materials on my own.", objectives = "" }
WordHunterWoW_QuestEN[72603] = { title = "What Words Are Worth", description = "Let me just grind these flowers and... there we are, all ready! \n\nTake these items and place them in the incense burner. Together with Bovan's necklace, I can entreat Ohn'ahra to help us find him. \n\nWith luck, she will give us a vision.", objectives = "" }
WordHunterWoW_QuestEN[72604] = { title = "Desperate Rescue", description = "I should have known I could not trust the centaur. They may provide token amounts of aid, but they would never risk themselves for us.\n\nLet us focus on the matter at hand. We cannot allow Bovan to remain in centaur captivity! I will set out immediately for Nokhudon Hold. \n\nMeet me there as quickly as you can.", objectives = "" }
WordHunterWoW_QuestEN[72605] = { title = "Saving Bovan Windtotem", description = "Time is against us, {name}. We must find Bovan as quickly as possible.\n\nThis hold is teeming with centaur. Our search will go faster if we split up--and it will be easier to slip by the patrols.\n\nTake one of these potions I brought. It should help you go undetected, but beware of the Nokhud wardogs. If Tomul spoke correctly, they will sniff you out.\n\nSearch the area for Bovan. If you find him, get him out. Do not wait for me.", objectives = "" }
WordHunterWoW_QuestEN[72606] = { title = "See Red", description = "Nokhud. Gelkis. Magram. Kolkar. They are all the same...\n\nThey plague the land. They murder my people. No more!\n\nI will end this centaur threat. Here! Now!", objectives = "" }
WordHunterWoW_QuestEN[72607] = { title = "Old Hatreds", description = "<Baine is still breathing heavily from his recent battles.>\n\nI will not leave... until Jamoku pays... for what he has done...\n\nI will avenge Bovan... no matter the cost...", objectives = "" }
WordHunterWoW_QuestEN[72609] = { title = "Case Closed", description = "You are lucky we arrived when we did. We intercepted the Nokhud reinforcements about to flank you during your fight with Jamoku.\n\nWe lost two of our number in that battle. Their bodies have already been recovered. Bovan's is the last.\n\nThe Nokhud will not take long to rally and hunt us down. We must leave now.\n\nHead to Toghusuq Village, where the tauren are encamped. We will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[72611] = { title = "Letting Go", description = "The Shikaar lost two of their own during the battle. All of Tomul's reinforcements... they volunteered to help, of their own will.\n\nI... have much to consider.\n\nAfter speaking with the Shikaar, we decided to honor our dead together. We have blended our funerary rites into one ceremony for this occasion.\n\nWe would be honored if you would stay and participate.", objectives = "" }
WordHunterWoW_QuestEN[72623] = { title = "Dragonflight (60-69) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72628] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72631] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72644] = { title = "An Urgent Matter", description = "Hello {name}. I was told to give you letter. The messenger mentioned it was urgent.\n\nThe crest on it seems to be from SI:7. I would read it right away if I were you.", objectives = "" }
WordHunterWoW_QuestEN[72650] = { title = "Warm Winds and Water", description = "Kirygosa wrote me after leaving Stranglethorn some years ago. She said it was beautiful and balmy, but not very quiet. I presume--and hope--she has found peace in Pandaria.\n\nIf I am honest with myself, I should not be surprised that she hasn't answered the Isles' call. Yet, we must do our duty and seek her out. If I am doubly honest with myself, I would have any excuse to see her again.\n\nLet us take a break from these chilly winds and visit the Jade Forest.", objectives = "" }
WordHunterWoW_QuestEN[72651] = { title = "Carp Care", description = "The village carp bring fortune and peace. Their well-being reflects the health of the village.\n\nThe carp thrive on special food made from worm meal and vegetable paste. It's not as unpleasant as it sounds, especially after we finish dehydrating it into neat little blocks.\n\nHere! Just toss it gently in the water near them.\n\nTheir ponds also require cleaning, so please skim any debris you find.", objectives = "" }
WordHunterWoW_QuestEN[72652] = { title = "Self Care", description = "How strange and wonderful it is to be in Kiry's own home.\n\nThat being said, I can't help but notice it is an absolute mess in here. She spends all this time helping with the villagers, I have a feeling that she doesn't reserve time for herself. Typical Kiry... <Kalecgos sighs.>\n\nWould you mind tidying this place up a bit, {name}? I'm sure she'd be glad for the help.", objectives = "" }
WordHunterWoW_QuestEN[72653] = { title = "Local Deliveries", description = "I've been cultivating a new flower in this land. It's quite versatile, but the villagers and I are still refining its various uses.\n\nI just harvested my latest batch today. Will you help me deliver them?", objectives = "" }
WordHunterWoW_QuestEN[72654] = { title = "Up, Up, and Home", description = "Honest work for an honest day. Thanks, {name}.\n\nWhy don't we have some tea and conversation at my home? Just tell me when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[72655] = { title = "A Drink with Kalecgos", description = "<Kalecgos is quiet for a moment, a wistful look on his face.>\n\nI'd call upon Nozdormu to help us pass the time, but he'd tell me that I should be able to handle this.\n\nSo... the Drunken Hozen. If Kiry recommends it, then let us go!", objectives = "" }
WordHunterWoW_QuestEN[72656] = { title = "Winterspring", description = "Haleh, Matron Protectorate, presides over Winterspring. Even after defeating the power hungry mage Umbranse, she continues to find and dispel danger in her homeland. As the last living consort of Malygos, she tirelessly upholds his legacy as a guardian of magic.\n\nHer return would greatly strengthen the blue dragonflight.", objectives = "" }
WordHunterWoW_QuestEN[72657] = { title = "A Protector of Magic", description = "I am very curious about Haleh--she is one of the last living consorts of Malygos. I am grateful for her going to Malygos in his time of need.\n\nI will admit, I have spent some time spying on her. She is a blue dragon through and through. Studious, proud, and one of the more careful ones around magic. \n\nI do feel most suited to be the one to visit her about the call of the Isles. Take my portal when you are ready. I shall meet you there.", objectives = "" }
WordHunterWoW_QuestEN[72659] = { title = "Test Subject", description = "Today is day forty-one without finding a harmful artifact. I am further delighted to report that while you were away, a handful more proved harmless. Perhaps my hunt in Winterspring is almost concluded!\n\nCome to think of it... you have some magical ability, don't you? Or enough bravery to help me test some more artifacts?\n\nDo not be nervous. None of them will permanently hurt you. Artifacts with that kind of dangerous power were taken care of in my first year here.", objectives = "" }
WordHunterWoW_QuestEN[72660] = { title = "Owl of a Sudden", description = "While you were working, I was inspecting the totemic ruins you retrieved. There has always been something odd about the Hidden Grove. It used to be occupied by a robust population of harmless white hares. Now there are only maddened owlkin and strange totems...\n\nI put the pieces together. It is no masterpiece, but hopefully we can glean a stronger magical effect from the whole.\n\nMaybe it will even make us sprout some feathers and fur. You would think as a blue dragon I would enjoy the cold, but no.", objectives = "" }
WordHunterWoW_QuestEN[72661] = { title = "A Wyrm Rest", description = "Oh dear. I have an idea. Speak to me when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[72662] = { title = "Resupplying Supplies", description = "The Nokhud have been striking at outsiders crossing into the plains. This is no doubt their handiwork.\n\nThis survivor says that most of their food supplies were destroyed in the ambush. We should try to help out.\n\nLet's collect meat from the plentiful game around the Watering Hole. That should be enough to cover their immediate needs.", objectives = "" }
WordHunterWoW_QuestEN[72663] = { title = "Pinewood Trail", description = "If Bovan is not dead, and he is not here, then either he is still out there... or he has been captured. Given Tomul's message, I fear it's the latter.\n\nThe Windtotem are safe for now, but with an attack possible at any moment, they can't spare any braves to go after Bovan.\n\nIt looks like it is up to us. Let us head to Pinewood Post.", objectives = "" }
WordHunterWoW_QuestEN[72664] = { title = "Eggs in Abundance", description = "<Flaps does a spin and deposits a drool-soaked note into your hand.>\n\n{name}, the Ruby Life Pools are overwhelmed with dragon eggs ready to hatch. We are excited to welcome these blessings to Azeroth, but we do not have enough whelptenders to mind them all.\n\nPlease visit me at the Lifeshrine so we may discuss a potential solution.\n\n- Amella", objectives = "" }
WordHunterWoW_QuestEN[72665] = { title = "Whelptender's Wisdom", description = "Our egg-tenders report a new clutch of eggs is soon to hatch. Ordinarily, a whelptender would take each newly hatched dragon and raise them with their flight. However, not all dragonspawn are called to the life of a whelptender, and we are short of hands.\n\nGather wisdom from whelptenders of each flight in the gardens below the Lifeshrine. Agapanthus, an experienced whelptender of the blue flight, has offered his services as head of the Little Scales Daycare. But he will need your assistance.", objectives = "" }
WordHunterWoW_QuestEN[72666] = { title = "Daycare Director Agapanthus", description = "Amella has told me about the incoming whelps and about the daycare. Did you know Agapanthus is a renowned whelptender? I heard he fought back demons while rearing whelps! \n\nIf he's as amazing as they say, I have much to learn from him. I only just received my Calling, but I will help in any way I can.\n\nThe Little Scales Daycare is in Valdrakken. I will gather my things and meet you and Agapanthus there.", objectives = "" }
WordHunterWoW_QuestEN[72667] = { title = "Snack Run", description = "The whelps that visit the daycare eat snacks during their visit. A lot of snacks.\n\nIf there are going to be whelps that stay here with regularity, we will need even more rations to sate their endless hunger.\n\nHere is a list of snacks the whelps have taken to lately. I also ordered something for Sir Pringly, so be sure to get that as well.", objectives = "" }
WordHunterWoW_QuestEN[72668] = { title = "A Nurturing Environment", description = "Young whelps can be careless in how they treat their space. The daycare is effectively under siege day in and day out!\n\nHelp clean up the daycare. The new whelps will need a proper place to stay.\n\nI will not let one claw set down on unpolished stone or overgrown grass!", objectives = "" }
WordHunterWoW_QuestEN[72670] = { title = "Those We Left Behind", description = "In attempting to defend their home against the fury of the blue dragonflight, Shandaral's mages condemned the souls of their people to an eternity of crystalline torment. \n\nNow their echoes wander aimlessly, reliving their civilization's doom again and again for more than ten thousand years.\n\nI have found that some of the shades yet retain a shred of sentience. Perhaps they can be reasoned with--convinced to free themselves from the mire of their own ancient fear and pass on at last.", objectives = "" }
WordHunterWoW_QuestEN[72674] = { title = "A Shattered Legacy", description = "Shandaral's reckless use of the crystal focus placed too much stress on the relic, causing it to shatter. Its fragments have been scattered amidst the crystalline permafrost.\n\nI can recreate the focus, but I will need you to collect enough of those shards to give me something to go on. You should be able to find them amidst the piles of crystal refuse scattered throughout the area.\n\nTake heed, {class}. Those shards may still hold fragments of the mages's memories from that fateful day.", objectives = "" }
WordHunterWoW_QuestEN[72679] = { title = "An Arcane Requiem", description = "The time is upon us, {name}. With your help, most of the restless echoes of Shandaral have been quelled. However, some yet remain whose rage and sorrow burns too brightly to be eased by mere words.\n\nUsing the shards that you recovered, I have managed to recreate a facsimile of the crystal focus that brought Shandaral to ruin. Using it here should bring the anchored spirits to bear and give us an opportunity to grant them final rest.\n\nBe on guard. I do not know how their long-held sorrows will manifest.", objectives = "" }
WordHunterWoW_QuestEN[72681] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "" }
WordHunterWoW_QuestEN[72686] = { title = "Storm Surge", description = "{name}, the Primalists have managed to summon fierce Elemental Storms all across the Dragon Isles. \n\nWhen a storm is active go to it and slay the imbued creatures there. \n\nThen collect the Elemental Overflow from the slain foes. Be aware that the stronger the foe, the more Elemental Overflow you will collect.\n\nWe must not let the Primalist elemental corruption grow unchecked.", objectives = "" }
WordHunterWoW_QuestEN[72688] = { title = "Renown Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[72690] = { title = "Renown Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[72693] = { title = "Renown Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[72700] = { title = "Flashfrost Flyover - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72705] = { title = "Wild Preserve Slalom - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72706] = { title = "Wild Preserve Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72707] = { title = "Emberflow Flight - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72708] = { title = "Dragon Isles Supplies", description = "<That proto-dragon must've snatched this bag of supplies off of an unlucky Dragonscale Expedition member.\n\nCataloger Jakes in Wingrest Embassy will know what best to do with it.>", objectives = "" }
WordHunterWoW_QuestEN[72709] = { title = "Funding a Treasure Hunt", description = "<Cataloger Jakes quickly flips through her own supply bag and pulls out a freshly drawn map.>\n\nOne of our archeologists just reported some new findings in regards to a lost artifact, suspected to be in this area.\n\nIf you'll donate those supplies to fund the archeologist's next expedition, you can have this map that points to a nearby treasure.", objectives = "" }
WordHunterWoW_QuestEN[72712] = { title = "The Best We Have", description = "I am glad you're here, {name}. \n\nThe storms have cleared and the creches are open. Now is the time to strike! I'm leading a team of scouts further into the Reach.\n\nWhen you're ready to depart, speak with Talon Damos. He's acting as my second-in-command. The dracthyr he leads will be accompanying us on our next reconnaissance mission.", objectives = "" }
WordHunterWoW_QuestEN[72713] = { title = "Inheritance", description = "Glad you could make it, soldier.\n\n<Damos gives you a sardonic salute.>\n\nThis is surreal. We're back in a place we knew long ago. Now it's in ruins. And it's crawling with all kinds of new wildlife. \n\nI guess it's true what they say. You can never go home again.\n\nEnough talking. Time to work. Emberthal wants this place locked down.", objectives = "" }
WordHunterWoW_QuestEN[72714] = { title = "An Interdisciplinary Approach", description = "The Dragonscale Expedition does not pose a threat to Sarkareth. The fact that Sarkareth and his followers would be so brazen as to attack them during their research...\n\n<Ebyssian furrows his brow.>\n\nSave as many Expedition members as you can. The knowledge in these ruins is priceless if it can unlock the secrets of our past, but it is ultimately worthless when weighed against the value of single innocent life.\n\nI will meet you in the ruins above when I am done here.", objectives = "" }
WordHunterWoW_QuestEN[72715] = { title = "Keeping the Flame at Bay", description = "It's not enough that Sarkareth kills our people, twists our heritage, and burns everything in his path. Now he seeks to pillage the creche of the Adamantine Vigil. \n\n<Emberthal snarls.>\n\nEbyssian and I will stay here while you push back the Sundered Flame. We'll meet you up top once the Expedition is secure.", objectives = "" }
WordHunterWoW_QuestEN[72717] = { title = "A Creche Divided", description = "This place... I have not been here for a long time. Not since before I was a Scalecommander. \n\nIt is a dark place, full of pain... and failure. \n\nThis was where Neltharion tested those he considered most worthy of his attention. He poked and prodded us with powers we could not understand or control.\n\nMany of us were found... wanting.\n\nPerhaps Sarkareth brought me here to test me the same way our father tested us.\n\nWill you walk with me?", objectives = "" }
WordHunterWoW_QuestEN[72729] = { title = "The Great Swog", description = "A peculiar coin fished up around the Dragon Isles.\n\nYou've heard rumors from fellow anglers of a creature in the Ohn'ahran Plains who collects such things.", objectives = "" }
WordHunterWoW_QuestEN[72734] = { title = "Apex Canopy River Run - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72738] = { title = "The Way to an Otto's Heart", description = "", objectives = "" }
WordHunterWoW_QuestEN[72739] = { title = "Uktulut Coaster - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72740] = { title = "Wingrest Roundabout - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
