WordHunterWoW_QuestEN[72746] = { title = "A Piece of Silver", description = "", objectives = "" }
WordHunterWoW_QuestEN[72747] = { title = "A Piece of Gold", description = "", objectives = "" }
WordHunterWoW_QuestEN[72748] = { title = "A Bag of Gold", description = "", objectives = "" }
WordHunterWoW_QuestEN[72749] = { title = "A Curious Coin", description = "", objectives = "" }
WordHunterWoW_QuestEN[72750] = { title = "Caverns Criss-Cross - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72754] = { title = "Academy Ascent - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72760] = { title = "Cliffside Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72769] = { title = "Garden Gallivant - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72773] = { title = "Learning Ingenuity", description = "There are some goblins within Valdrakken that are investigating an abandoned titan device. \n\nHonestly, they're causing quite a disturbance. Some are concerned their investigation could cause more harm than good.\n\nThe denizens of Valdrakken would appreciate you meeting these goblins to see if you can find a solution to their investigation.\n\nWithout destroying part of our city.", objectives = "" }
WordHunterWoW_QuestEN[72783] = { title = "Crafting Orders", description = "That's a nifty thing you got there from the titan device. Now hand it over!\n\nJust kiddin'! I wouldn't know the first thing about how to use that. Do you?\n\nGo talk to Mimzy Sprazzlerock. She's got a whole gig setup findin' folks to do something called \"crafting orders\".\n\nYou put up the goods, someone takes 'em and crafts something for you. \n\nSimple, right? Go talk to Mimzy to check it out! And don't tell her I sent you.", objectives = "" }
WordHunterWoW_QuestEN[72784] = { title = "Supporting the Cobalt Assembly", description = "{name}, excellent timing.\n\nHave you heard of the Cobalt Assembly? It was once a wondrous place where most of my kin lived.\n\nThe Sundered Flame forced us out and have taken it over. \n\nThere was a hope that we could take it from them, but the latest information from there shows we are fighting a losing battle.\n\nCan you lend us your support? Meet Venthi within the Cobalt Assembly if you can.", objectives = "" }
