WordHunterWoW_QuestEN[72819] = { title = "Shadowlands (60) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72831] = { title = "Creative Solutions", description = "I have always hoped that mages would once again walk the streets of Theramore. This, however, is not what I had in mind.\n\nIf this Sullied Banner truly intends to reconstruct a working mana bomb, then they must be stopped--but I will not repeat the mistakes Malygos made. There must be a way to reason with them. \n\nI shall place an enchantment upon you that will allow you to subdue the mages without killing them. See to it that they cannot continue their ill-intended actions.", objectives = "" }
WordHunterWoW_QuestEN[72832] = { title = "Aftershocks", description = "These precocious whelps seem to be trying to recreate the very bomb that leveled Theramore. Predictably, they have yet to succeed. Still, I would rather not give them the chance to stumble into a more effective solution.\n\nIf our dear Aspect wishes to avoid simply turning the whole lot of them into mana dust, then I suppose I can refrain from carpeting the ruin in spellfrost. Someone will need to go and repossess their banal attempts at ordinance, though.\n\nDo take care not to set them off, hmm?", objectives = "" }
WordHunterWoW_QuestEN[72833] = { title = "Breaking the Cycle", description = "With many of their rank-and-file captured, it is time to deal with the leader of this so-called Sullied Banner.\n\nI imagine Kalecgos wishes to take her alive. I have no such compunctions, but I am not a picky dragon. So long as we put a stop to her schemes, I care little what happens to her.\n\nHis plan, though troublesome, seems to have worked thus far. I am willing to give him the benefit of the doubt, at least for a short while longer.", objectives = "" }
WordHunterWoW_QuestEN[72854] = { title = "Our Enemies Abound", description = "Just when we get our feet back under ourselves, someone wants to knock us down again.\n\nThere are people who still think that we don't deserve this home, and they're willing to kill us to get what they want.\n\nAnd some old grudges never go away. Somehow, the Scarlet Crusade, or what remains of it, has gotten a toehold on Fenris Isle.\n\nGo to the southern wall of the Ruins of Lordaeron. Deathstalker Commander Belmont has got eyes on them.", objectives = "" }
WordHunterWoW_QuestEN[72855] = { title = "To the Sepulcher", description = "Faranell and Velonara already went to the Sepulcher to work on a piece of our plan.\n\nWe can hold the wall for now with just a few deathguards and dark rangers, but we need someone who can hit the Scarlets where they are. Preferably without losing more of our own.\n\nGo to the Sepulcher and meet with Velonara. You are the sharpened tip of our poisoned blade.", objectives = "" }
WordHunterWoW_QuestEN[72856] = { title = "Nothing Like the Classic", description = "We of the Royal Apothecaries have synthesized many nuanced plagues in recent years, in keeping with our agreement with the Desolate Council not to... overdo it.\n\nBut when it comes to rooting out Scarlet assailants, there really is nothing like the classic. The original plague that exists -- mostly -- only in the diseased tissue of surviving descendants.\n\nGo, gather up samples from this marvelous wildlife and bring them to me. I can put them to greater use.", objectives = "" }
WordHunterWoW_QuestEN[72857] = { title = "Boom Weed", description = "You've heard of Gloom Weed, you've heard of Doom Weed, now it's time for... Boom Weed!\n\nThat's right, another variety grows right here in Silverpine! And it can be used in combination with our alchemical formulas for a very incendiary outcome.\n\nGo and collect some for me. Just mind your eyebrows. You don't really need any eyebrows, do you?", objectives = "" }
WordHunterWoW_QuestEN[72858] = { title = "Acid Beats Paper", description = "While the Scarlet Crusade have taken Fenris Isle, they try to intimidate and cow our people in Silverpine Forest. \n\nWe cannot let them win either by strength or by terror. \n\nWhen you collect materials for Faranell's concoction, destroy any slanderous propaganda you find.", objectives = "" }
WordHunterWoW_QuestEN[72859] = { title = "A Proper Disguise", description = "Our plan is to send you to Fenris Isle, but first, you must look the part.\n\nWe've scouted out a group of Scarlet solders training in Valgan's Field, supervised by a lieutenant. That lieutenant's armor should let you walk deep behind enemy lines, unnoticed.\n\nTake it from them, however you see fit. I don't need to know how.", objectives = "" }
WordHunterWoW_QuestEN[72860] = { title = "Fear is Our Weapon", description = "The Scarlet Crusade is recruiting. Apparently, when you want to blame all your problems on someone else, people flock to the lies.\n\nBut that's a choice that they're going to live to regret. We're not the problem here. THEY attacked OUR home.\n\nTake one of the banshees with you. Between the two of you, those recruits will be scared to death.", objectives = "" }
WordHunterWoW_QuestEN[72861] = { title = "The Scarlet Spy", description = "Now it's time to sneak you onto Fenris Isle. I know this armor isn't exactly what you want to wear, but it will help you move around without being noticed.\n\nApproach the isle on their level. No fancy sky maneuvers.\n\nOnce you've put on the armor, find a way to get across the water. There's a quartermaster who can tell you where to go from there.\n\nFrom there, you know how to raise bedlam.", objectives = "" }
WordHunterWoW_QuestEN[72862] = { title = "Among Us", description = "We could use those recruits to bolster us, but those dreadful undead are harrying our supply lines! They will all be put in the ground permanently, soon enough.\n\nCould you check on our stockpiles to make sure we've got enough for your recruits? Of course the good stuff has already gone up to Fenris Keep for the Commander, but everyone has to eat.\n\nWell, almost everyone.\n\nGet a move on, lieutenant.", objectives = "" }
WordHunterWoW_QuestEN[72863] = { title = "The Flight of the Banshee", description = "With the island's defenses weakened and the cannons and mages silenced, we're ready to safely bring in our troops once more.\n\nYou didn't think you would have to fight all of them by yourself, did you? \n\nI know you could, but leave some for the rest of us, too.\n\nWhen you're ready to call the others in, let me know.", objectives = "" }
WordHunterWoW_QuestEN[72864] = { title = "Death to the Living", description = "Now it's time for them to pay. They'll wish they never set foot in our lands and threatened our home.\n\nWe will drive them out, we will drive them into the ground, and we will leave them to rot.", objectives = "" }
WordHunterWoW_QuestEN[72865] = { title = "This is the Hour of the Forsaken", description = "We haven't seen the Scarlet Crusade put this many fresh soldiers on the field in a long time.\n\nAnd we know that they didn't get here on their own. Someone's guiding them. Someone who's fought Forsaken before.\n\nSomeone I remember well.\n\nCome with me, and let's put an end to Commander Forsythe.", objectives = "" }
WordHunterWoW_QuestEN[72866] = { title = "Return to Lordaeron", description = "Let's get back behind the walls and meet the others. I think Belmont had the time of his unlife with you, getting to cut down Scarlets again.\n\nBut this isn't the end of the Crusade. Even though they lost, they might still turn this into yet another way to recruit.\n\nWe'll be ready if they ever come for us again. Or our neighbors.\n\nCome on, let's get back to the Ruins of Lordaeron.", objectives = "" }
WordHunterWoW_QuestEN[72867] = { title = "I Am Forsaken", description = "We have fought to win back our home. We have fought to keep it safe. \n\nYour courage and strength are inspirational to the Forsaken. And with you, we know we have our champion. \n\nGo, they want to see you.", objectives = "" }
WordHunterWoW_QuestEN[72872] = { title = "Culling the Deep", description = "Have you seen these deepflayers before? Well, of course you have! You were almost eaten by one!\n\nThey're getting a little too cozy to me and my people's settlement nearby, and need to be dealt with. Inside the cave, outside the cave, they're all over the place!  That's why I came here in the first place.\n\nSince I can tell we'll be ramblin' round with each other for a bit, why not give me a hand?", objectives = "" }
WordHunterWoW_QuestEN[72873] = { title = "It Was Not Enough", description = "You're smellin' real down and out there, kid. Can't imagine what you been through to end up here.\n\nWell, it don't matter! We niffen ain't the sort to leave anyone behind. Especially not people who're about to be served up as a deepflayer's snack!\n\nThis master sniffin' snout of mine can smell you didn't come down here to our Zaralek Cavern alone. What say we get you out of those crystals and find your friends!", objectives = "" }
WordHunterWoW_QuestEN[72874] = { title = "Secrets From Our Father", description = "Look closely, {name}. You see this odd chunk of metal in the deepflayer muck?\n\nI have felt my head swimming since we arrived in these caverns. I thought it was just the ceaseless prattling of our whelp, Wrathion, but this object here may prove otherwise.\n\nI will continue my efforts to unlock this relic's secrets. Seek out similar pieces in the nearby caves. A dark theory is emerging, though we will need more information before I am willing to confirm it.", objectives = "" }
WordHunterWoW_QuestEN[72878] = { title = "Slime Time Live", description = "{name}, if I could grab your ear again, my dear?\n\nSince making it back to Loamm, I've noticed that some of our incense pots have gone missing.\n\nIncense is what we use to mark our trade routes, and find our way back to Loamm. It's very important that we replace the missing incense as soon as possible.\n\nBy the way, we make our incense from snail slime, so you're going to have to wrangle some snails first!\n\nOnce you're done, Citros can help you out with the rest.\n\nSay hello to Marie Shellie for me!", objectives = "" }
WordHunterWoW_QuestEN[72879] = { title = "Smells like Kith Spirit", description = "Well, it's not too often we see uplanders around here!\n\nHoneypelt must have a good reason for sending you my way, she doesn't trust just anyone with her incense.\n\nA kith's incense is their pride and joy. Each one smells unique, and we use them to identify each other. \n\nMaking incense is a delicate business. Just head over to that cauldron and Marie Shellie and I will help ya out with whipping up some replacements.", objectives = "" }
WordHunterWoW_QuestEN[72880] = { title = "Incense Gratification", description = "That's some real potent incense you made! Usually it takes time to get this good!\n\nNow, I've got some of my own brewing to do, so you're gonna have to go out and set those up by yourself.\n\nOnce you're finished I'm sure Honeypelt will be mighty keen on hearing about it! Best follow up with her when you're done.", objectives = "" }
WordHunterWoW_QuestEN[72881] = { title = "A Swallow's Tale", description = "Uplander!\n\nI'm Effervesta, Lady Redolence to the niffen of Loamm--the daughter of their leader. No need for formalities though, you can just call me Effie!\n\nKeep this between you and me, but we're a bit behind on some shipments to Glimmerogg, and the Drogbar are definitely not happy one bit! You've already been so helpful to Elder Honeypelt... maybe you can give me a hand too?\n\nOur swallows keeper, Nevroll, might be able to dig up some dirt on the issue. \n\nWill you go talk to him, please?", objectives = "" }
WordHunterWoW_QuestEN[72882] = { title = "Flown the Coop", description = "They're gone! Just... gone!\n\nThe swallows, Nevroll, all of it!\n\nAnd now you say that Effervesta told you that we're behind on our shipment of swallow nests to the Drogbar?\n\nThis is really bad, Uplander. \n\nIf you want to help, you can start by bringing back as many birds as you can find.\n\nI'll see if I can scrape together any useable nests for the Drogbar in the meantime.", objectives = "" }
WordHunterWoW_QuestEN[72883] = { title = "A Bitter Pill to Swallow", description = "<The corpse of a single cave swallow rests on the cavern floor. You should tell Cinnam.>", objectives = "" }
WordHunterWoW_QuestEN[72884] = { title = "Expedition Effervesta", description = "My daughter's gone missing--we have to find her!\n\nAs High Redolence, I may be the next target. {name}, will you come with me?\n\nI can still smell her, faintly. She has to still be in Loamm somewhere.\n\nWe have to hurry!", objectives = "" }
WordHunterWoW_QuestEN[72886] = { title = "Suss Out the Imposter", description = "Do I smell... Nevroll?\n\nIf he's the kidnapper, that must mean he's also behind the missing shipment!\n\nI don't think it's safe for me to go in there, {name}. \n\nPlease, rescue Effie!", objectives = "" }
WordHunterWoW_QuestEN[72900] = { title = "Keeper of the Ossuary", description = "Greetings, {name}. While I continue to search for the remaining blue dragons, I could use your aid in another matter.\n\nAlexstrasza and I plan on laying to rest the remaining essences of Malygos and Sindragosa. She has held on to their lingering essences after both were slain years ago.\n\nSenegos said there was a time where dragons would be laid to rest in the Veiled Ossuary. Unfortunately, the place is a mess.\n\nHe's gone ahead to clean the area up with Stellagosa. Could you aid them?", objectives = "" }
WordHunterWoW_QuestEN[72908] = { title = "Sight Beyond Sight", description = "I had not expected to find djaradin here, though it does not surprise me. Legends tell of their elders slumbering beneath the earth. It makes sense that some would delve underground in search of them.\n\nTheir forces are heavily guarding this outer area. I recognize the magic their scouts are using--it is farsight, powered by those totems near them.\n\nI spotted a larger totem at the top of the nearby tower. If you can figure out how to power it, we can use it to search the caldera from afar.", objectives = "" }
WordHunterWoW_QuestEN[72909] = { title = "Legends of the Zaqali", description = "Because of our recent conflicts, I have been researching the djaradin. Our archives had little information on their elders.\n\nLegends say that they were once great warlords who now slumber beneath the earth. The djaradin believe they will awaken and lead them to a brutal victory against the dragonflights.\n\nWe need to know what we are up against. There is an empty shrine just below us that resembles the ones housing the elders. \n\nWe may find some answers there.", objectives = "" }
WordHunterWoW_QuestEN[72910] = { title = "Know Thy Enemy", description = "That djaradin called her people the \"Zaqali\"--but my troops did not report any information regarding a second active djaradin tribe in the Dragon Isles. I detest an unknown in war.\n\nWe will need to learn what we can about them--and quickly--in order to assess their strengths and weaknesses. I have found the best way to know a culture is to examine how they make war.\n\nSlay any you find in the nearby area and take their armaments. I will expect your report.", objectives = "" }
WordHunterWoW_QuestEN[72911] = { title = "Take Out the Head", description = "While you and Ebyssian were away, I had an epiphany.\n\nThat corrupted caldera is at the center of the Zaqali elder's slumbering prison and their war camps. Whatever is located within is the key to what the Primalists are planning.\n\nIt is lightly guarded as well. Only a Primalist and a Zaqali priest. If we take them out, we can discover what I believe will be the truth behind all of this.", objectives = "" }
WordHunterWoW_QuestEN[72912] = { title = "Consequences", description = "Shadowflame...\n\nDid Iridikron know this was here? Did he corrupt his brother? Or has Fyrakk fallen to the temptation?\n\nOnly ignorance or arrogance tempts fools to seek it out, believing they can master dark forces that not even Neltharion could. It infected him, slowly, like a gangrenous lesion until finally he succumbed to madness.\n\nSo too will Fyrakk.\n\nI will not take that risk with Sabellian. \n\nHe was burned badly before I was able to fly you to safety. Let us assess the extent of the damage.", objectives = "" }
WordHunterWoW_QuestEN[72913] = { title = "Battlefield Triage", description = "Our situation is less than ideal, we will have to improvise. I can conduct flame to earth to create magma. Shadowflame could behave similarly.\n\nThe Primalists are summoning earth elementals nearby. If we extract their cores, I can use them to contain the shadowflame infecting Sabellian's burn.\n\nThe Zaqali's totems should already be attuned to the elements here. It will make the siphoning process much more efficient.\n\nSabellian will need to come with us. I must keep an eye on him--for his sake.", objectives = "" }
WordHunterWoW_QuestEN[72914] = { title = "Rushing Quality", description = "Look ahead! The djaradin have cleared away from the northeastern side of the caldera to augment their forces near the elders.\n\nThere is an altar bordering the lava pool that appears safe for now. We can set up our spell components there.\n\nLet us hurry before the djaradin return.", objectives = "" }
WordHunterWoW_QuestEN[72915] = { title = "Alliance of Convenience", description = "The Primalists have a sizeable force of djaradin guarding them while they complete their work.\n\nEven in small numbers, djaradin prove to be formidable opponents when allowed to engage in battle on their own terms. It is far better to bring the fight to them, leaving as little time to react as possible.\n\nTake them out. We cannot have them encroaching on the space we have managed to carve out thus far.", objectives = "" }
WordHunterWoW_QuestEN[72916] = { title = "Shut Them Down", description = "Up ahead, the Primalists are working to awaken the Zaqali's final elder.\n\nWhen we used the farsight totem earlier, I observed that they were draining something from the elder. Now I realize it is likely an attempt to dispel the magic keeping the elder in stasis. They are using elemental cores to contain the magic in the same way we did to cleanse Sabellian.\n\nFyrakk absorbing shadowflame is disastrous. We cannot add an elder awakening to that threat. We must halt their efforts.", objectives = "" }
WordHunterWoW_QuestEN[72917] = { title = "From Hell's Heart", description = "No longer can we allow Fyrakk to lie here peacefully, twisting himself with shadowflame and becoming a threat on par with Deathwing. We must act! Is it dangerous? Yes. But not to do anything would be catastrophic.\n\nI have ripped gronn apart with my bare claws before. Those battles were gambles, this one is not. Slaying a proto-dragon with a weapon meant for dragonslaying is obvious. It is logical. It is guaranteed.\n\nI will not tremble before an opportunity to end this now.", objectives = "" }
WordHunterWoW_QuestEN[72918] = { title = "No Dragon Left Behind", description = "I... cannot move so long as this spear remains in my side. But we need to follow Fyrakk's trail.\n\n<Ebyssian grunts sharply, his breathing labored, claws digging into the dirt.>\n\nRemove it. I can... bear the pain it will cause.", objectives = "" }
WordHunterWoW_QuestEN[72919] = { title = "Raked Over the Coals", description = "The shadowflame has already corrupted Fyrakk irreparably. Every place in Zaralek darkened by his wings has been lit ablaze with shadowflame.\n\nWe cannot leave it behind and let it fester--it will need to be extinguished while it is still kindling, lest we allow its corruption to take root.\n\n<Ebyssian coughs, then winces.>\n\nSabellian and I cannot take to the air in this state. Disperse the flames with your drake. We will follow you below and meet you back at Loamm.", objectives = "" }
WordHunterWoW_QuestEN[72920] = { title = "The Endless Burning Sky", description = "Fyrakk must have breathed shadowflame upon the niffen on his way out of the cavern. There is too much fire for it to have merely sloughed off of him.\n\nHe did this on purpose.\n\n<Ebyssian clenches his staff tightly. He looks weary for a moment. Only a moment.>\n\nWe will save Loamm. All of Loamm. No more lives will be lost.", objectives = "" }
WordHunterWoW_QuestEN[72921] = { title = "On the Trail Again", description = "Ah... the Veiled Ossuary. I was given the task to be a sort of gravekeeper, which included keeping wildlife away from the area.\n\nI had a rather fun spell split up within several tomes kept within this place to deal with such pests. \n\nThe other blue dragons did not approve of my... reckless methods, so I had to keep the tomes hidden.\n\nHere, allow me to cast a spell on you to grant you the sight to find these old tomes.\n\nOnce they are all gathered, we can cleanse this place of the invasive wildlife.", objectives = "" }
WordHunterWoW_QuestEN[72922] = { title = "Fading Embers", description = "This is a difficult situation, my friend. Wounds and insecurities cannot be easily dismissed. Only time--and cooperation--can soothe the sting born of longstanding rivalries.\n\nBut there are more urgent matters to address. If there is a large force of drakonids still loyal to the memory of Neltharion, this land is much more dangerous than any of us expected.\n\nEmberthal still pursues Sarkareth--alone. She must be made aware of the threats that surround her. We must find her and give her aid.", objectives = "" }
WordHunterWoW_QuestEN[72923] = { title = "A Whisper to Sabellian", description = "Our assault on Brimstone Garrison will not work without Sabellian and his relentless and mighty dragons. We must convince him that our objectives are aligned.\n\nIf we appeal to him as a tactician and general, I'm sure he will help us... I hope.\n\nWe will find him with his troops at the Djaradin Assault.", objectives = "" }
WordHunterWoW_QuestEN[72924] = { title = "Appealing to the Black Prince", description = "Our assault will not be successful without the stealth and cunning of Wrathion and his Blacktalon agents. We must convince him to help us.\n\nThankfully, I know in his heart he will not deny someone in need--especially if they flatter him.\n\nLet us go to Wrathion at the Obsidian Rest and try to sway him.", objectives = "" }
WordHunterWoW_QuestEN[72925] = { title = "With Our Powers Combined", description = "Emberthal is waiting for us in front of the Brimstone Garrison.\n\nCome, {name}. She will be pleased to see we have rallied the full might of the black dragonflight to aid her cause.", objectives = "" }
WordHunterWoW_QuestEN[72926] = { title = "In the Right Hands", description = "There are several weapons of historical value that I believed were lost to time. I would bet my talons that they are here at this garrison.\n\nThe dragonspawn and drakonid loyally cling to the memory of my long-dead father. Misguided fools. \n\nThey have access to my father's forges and weapons, and it is likely the very weapons I thought lost are stored nearby. \n\nIf they find out what they have, they will use the weapons against us. They cannot remain in their claws.", objectives = "" }
WordHunterWoW_QuestEN[72927] = { title = "Finding Sarkareth", description = "Now that we have a foothold within the garrison, we can extend our search. We will hold off the forces of Aberrus here while you find Emberthal and aid her in reaching Sarkareth. We will join you as soon as we secure the front here.", objectives = "" }
WordHunterWoW_QuestEN[72928] = { title = "Wipe Them Out", description = "Do you know what I see when I gaze upon the Brimstone Garrison?\n\nTraitors.\n\nThese soldiers believe themselves followers of the black dragonflight, yet they ignore us, the true heirs to Neltharion, and bend a knee to the specter of our malevolent father. \n\nThis cannot be allowed to stand. \n\nShow them the error of their ways.", objectives = "" }
WordHunterWoW_QuestEN[72929] = { title = "Cracking His Shell", description = "We have seen shields like this before. Sarkareth is drawing on the power of Aberrus to protect himself while he finds his way in.\n\nCowardly, but clever.\n\nDisrupt the conduits that are supplying his shield power, and we should be able to reach him.", objectives = "" }
WordHunterWoW_QuestEN[72930] = { title = "Stopping Sarkareth", description = "This is our last chance, {name}. If we allow Sarkareth to slip in to Aberrus, he may gain power that puts him beyond our reach. We must stop him now!", objectives = "" }
WordHunterWoW_QuestEN[72931] = { title = "Forward Camp", description = "Since Sarkareth now wields the power of Aberrus's defenses, he has an army that will shield him from us.\n\nThe next step for us will be to establish a stronghold inside the garrison. That way we can search it without interruption. \n\nMeet me there.", objectives = "" }
WordHunterWoW_QuestEN[72933] = { title = "Rolling Out", description = "I remember having so much fun rolling these creatures up with my spells. Unfortunately, I fear these old bones will not let me move as quickly as I once did.\n\nI would love for you to give it a shot. Let me live vicariously through you! \n\nThe more creatures you roll up, the bigger the ball becomes. The bigger the ball, the bigger the creature you can roll out.\n\nSpeak to me and I shall give you my special arcane ball to roll up the creatures around here.", objectives = "" }
WordHunterWoW_QuestEN[72934] = { title = "Lest We Forget", description = "We will be joined shortly by Kalecgos and Alexstrasza. Before then, I have a request.\n\nThere was a tradition to have gravestones set before your death. It allowed you to choose where you would rest when you passed.\n\nIt was the job of the caretakers to update the gravestones and deposit the lingering essence of arcana at the site.\n\nBefore our guests join us, would you help me in this task? \n\nTake this list, and these graves. Update the existing graves and place the new ones.", objectives = "" }
WordHunterWoW_QuestEN[72935] = { title = "Archives Return", description = "It is not unusual that Malygos and Sindragosa would have such powerful memories. From what I understand, their deaths were particularly painful. Both slain by adventurers.\n\nIt breaks my heart to think of Sindragosa enduring death not once, but twice after being raised by the Lich King.\n\nBut enough of this old dragon's ramblings. Stellagosa and I will meet you back at the Azure Archives.", objectives = "" }
WordHunterWoW_QuestEN[72936] = { title = "Azuregos's Support", description = "Many blue dragons have returned, and many others have informed me of their plans to make their ways to the Isles.\n\nThere are a few key members of the flight, however, that I have not heard from. One of them may be able to help: Azuregos, stationed within the Nexus in Northrend. \n\nYou, myself, and Sindragosa will travel to meet Azuregos. He has ignored all of my attempts to contact him from afar.\n\nThanks to the oathstone being empowered, Sindragosa can now travel further than ever before.", objectives = "" }
WordHunterWoW_QuestEN[72937] = { title = "Unusual Disruptions", description = "Of course I can help track down the missing blue dragons. However, I have a mess on my hands that must be addressed first.\n\nMoments ago, several bursts of arcane energy swept through the Nexus, followed by attacks of strange arcane creations.\n\nI can create a method of tracking down the blue dragons if you can put down the locations of this wild arcana.\n\nTake this staff--do not break it--and use it on three locations within the Nexus. Oh, and prepare yourself for a fight.", objectives = "" }
WordHunterWoW_QuestEN[72938] = { title = "Archival Arrival", description = "I have crafted a magical globe to help you find the remaining blue dragons. It should give you their rough locations.\n\nNow go. On top of everything else I was working on, I must now investigate these \"memories\" that attacked the Nexus.\n\nI shall get to the bottom of it.", objectives = "" }
WordHunterWoW_QuestEN[72939] = { title = "Theramore", description = "According to Azuregos's notes, the blue dragon Surigosa was last seen investigating a sect of rogue mages known as the Sullied Banner. \n\nSurigosa's last missive stated that she intended to travel to the ruins of Theramore. Perhaps she uncovered traces of the Sullied Banner there. Either way, if Surigosa is to be found, Theramore seems the best place to search for her.", objectives = "" }
WordHunterWoW_QuestEN[72940] = { title = "Where in the World is a Lost Blue Dragon?", description = "Azuregos has narrowed down the locations of the missing blue dragons.\n\nEach of us will handle finding several of them. I would entrust you to aid us in finding a few others.\n\nChoose where you'd like to go first.", objectives = "" }
WordHunterWoW_QuestEN[72941] = { title = "Ancestral Advice", description = "I have a message for my descendent. It is very important.\n\nI understand you are new to our language. I will try to speak in small, 303(100)-easy words. When you are ready to give your full attention, I will 303(90)-share my message.", objectives = "" }
WordHunterWoW_QuestEN[72942] = { title = "Veiled Trouble", description = "I was hoping that we would find a way to dispel these strange arcane memories from what remains of Malygos and Sindragosa.\n\nIt appears they've grown more out of control than I expected. \n\nPlease, accompany some of the gathered blue dragons to the Veiled Ossuary and help Azuregos.\n\nSindragosa and I will remain here, and investigate what to do about this situation.", objectives = "" }
WordHunterWoW_QuestEN[72944] = { title = "Sending Stone: Protest", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[72945] = { title = "Our Path Ahead", description = "I have a message for Chief Kranac Sagesnow. I believe that it is not too late to lead our people down a 303(80)-better path.\n\nHowever, if he chooses the wrong direction, I see only 303(90)-darkness ahead for our people. \n\nWhen you are ready, I will 303(80)-impart this message.", objectives = "" }
WordHunterWoW_QuestEN[72946] = { title = "Veiled Ossuary Chaos", description = "Malygos and Sindragosa's essences have created this massive arcane disruption. Their memories are running around the Veiled Ossuary trying to drain the arcana out of the graves!\n\nOur combined efforts are merely keeping the energies at bay. We need the memories in the nearby area disrupted.\n\nOnce they are dispelled, we should be able to remove this barrier to reach the essences inside.", objectives = "" }
WordHunterWoW_QuestEN[72947] = { title = "Memories of Old", description = "Three incredibly powerful memories have formed throughout the Veiled Ossuary.\n\nSoon their energy will be so vast that they will be able to create their own arcane constructs... thus overwhelming this place.\n\nTake them down, so we can weaken this barrier and reach Malygos and Sindragosa's essences!", objectives = "" }
WordHunterWoW_QuestEN[72948] = { title = "What Still Remains", description = "The barrier is weakening, thanks to your aid. In a moment it will be broken down.\n\nOur main priority is recovering Malygos and Sindragosa's essences. Something has gone very wrong with laying them to rest. There are a few theories I have regarding their current state. We can speak about it as we enter.\n\nLet me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[72949] = { title = "Swiftly to the Archives", description = "I can hear the pained cries of rage and agony from these essences. I suspect this was triggered after attempting to put them to rest. \n\nThey were dormant for a time, but the combined rage of both Malygos and Sindragosa merged together to create this phenomenon. \n\nQuickly, we must make for the Azure Archives and inform Kalecgos and Sindragosa of this!\n\nTogether, we may be able to finally give them the peace that they deserve.", objectives = "" }
WordHunterWoW_QuestEN[72950] = { title = "The Last Conflict", description = "Malygos and myself both suffered horribly violent ends. The remains of our essences have been trapped in an endless loop.\n\nThey must be reformed, and broken out of that loop. To do so will require a tremendous amount of concentrated power.\n\nWe will have to utilize every amount of arcane energy within the Azure Archives... along with all of the assembled blue dragons.\n\nIt is the only chance we have to reform these spirits... and to put an end to their suffering.", objectives = "" }
WordHunterWoW_QuestEN[72951] = { title = "A Peaceful Farewell", description = "It brightens my heart to see everyone reunited, and Malygos and Sindragosa at peace at long last. \n\nIt is time that I give you all one last gift, something the blue dragons have not seen in quite some time.\n\nThe peaceful passing of one of their own.\n\nIt is my time, {name}. I should have flown beyond some time ago, but I could not leave with my kin still in disarray. \n\nWould you do an old dragon the honor of seeing me off on one last adventure?", objectives = "" }
WordHunterWoW_QuestEN[72952] = { title = "The Scary Vault of Ur", description = "Tacha's big ears heard some noise in one of the tunnels. We took a peek inside. I'm not going to lie: it's grim in there. Pretty terrifying. All sorts of horrible creatures. Not the sort of thing Tacha and I usually deal with up close.\n\nYou have experience dealing with monsters, right? Excellent. You go first. Don't worry. Once it's safe, we'll come in and join you. Really, it's the least we can do.", objectives = "" }
WordHunterWoW_QuestEN[72953] = { title = "Zskera Vault: Az", description = "We have discovered a series of vaults below the island. Neltharion hoarded treasures, accumulated knickknacks, and stashed away the results of his failed experiments.\n\nWhen I say he's a hoarder, I'm not kidding! He filled chamber after chamber, and in time, they were all forgotten... until now. Treasure awaits us behind these locked doors! Also, the occasional deathtrap. Also, treasure! Now we have the keys to unlock those doors.", objectives = "" }
WordHunterWoW_QuestEN[72954] = { title = "Zskera Vault: Ix", description = "Wulferd spotted some pirates making their way into the vaults this morning. If we don't act fast, they'll strip the vault clean!\n\nWe're going into the vault immediately. There's no time to lose. Will you be joining us?", objectives = "" }
WordHunterWoW_QuestEN[72955] = { title = "Zskera Vault: Kx", description = "I was afraid this might happen. The Sundered Flame is here. And they've discovered the Vaults.\n\nOf course, we have to stop them. Anything useful or dangerous, they're going to take straight to Sarkareth.\n\nI've had enough of his nonsense. Time for you to do what you do best.", objectives = "" }
WordHunterWoW_QuestEN[72956] = { title = "More Doors To Open", description = "There are still more vaults, but there aren't enough of us to explore them all.\n\nThat's where you come in. Could you look for more keys? Then we can continue exploring the vaults.\n\nTacha and I will stay here and work on documenting our earlier discoveries. That's tough work, but one of us has to do it. Okay, two of us. But it is a lot of work, I assure you.", objectives = "" }
WordHunterWoW_QuestEN[72958] = { title = "Save-A-Mole", description = "Perisimona told me about her life-mate, Tuberros, and what she knows about his disappearance.\n\nTuberros was guiding a client from the Dragonscale Expedition around some ruins here. It sounds as though they may have run into the Sundered Flame.\n\nI would rather not go after the Sundered Flame myself. Doing so would announce my presence to Sarkareth. \n\nWill you aid us by finding and rescuing Tuberros and his client? Maybe then he can help guide us to Neltharion's vault.", objectives = "" }
WordHunterWoW_QuestEN[72959] = { title = "Whose Vault Is It Anyway?", description = "I do not know what we will find in the vault or why Sarkareth wants access to it, but I hope we are not too late.\n\nBefore we continue any further, Tuberros should lead Rannan and Perisimona back to Loamm.\n\nCome and talk to me once you are ready to move forward.", objectives = "" }
WordHunterWoW_QuestEN[72961] = { title = "Charging Up", description = "Emberthal wanted this guy Sarkareth dealt with yesterday. I understand! I hate waiting too!\n\nThis door is frustratingly hard to crack... But! I have a plan because I always have a plan! My recipe for success is being one step ahead of everyone else. It's worked for me so far! Sorta.\n\nSo, about this plan... I might need your help!", objectives = "" }
WordHunterWoW_QuestEN[72962] = { title = "Open That Door!", description = "I am glad we are making progress but... I cannot shake a sense of foreboding of what awaits us inside. As Sarkareth learns about Neltharion, his intentions seem to get ever darker...\n\nI can only imagine what he is telling his people now--about me and about the other dracthyr. He will fracture our people forever.\n\nTalk to Rannan and see how much longer we have to wait. We can't waste more time.", objectives = "" }
WordHunterWoW_QuestEN[72963] = { title = "The Upper Hand", description = "It troubles me that Dezran would sacrifice himself so willingly for Sarkareth... And that Amythora and Marithos would leave Dezran to save him.\n\nWe both know the loss of waking in a new world. But Sarkareth wallows in the darkness of our past. I cannot let him continue to recruit our people.\n\nSarkareth awaits in the next room. I do not wish to kill him, but we must bring him to justice.\n\nLet me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[72964] = { title = "Singed", description = "Standing here, seeing these two Sundered Flame before me, there is no more anger. I see the confusion in their eyes and how they look at each other... They are so uncertain of their future.\n\nThey remind me of myself and the moment I emerged alone, my creche dead and forgotten by passing ages.\n\nI have to talk to them, {name}. Will you accompany me? As a friend?", objectives = "" }
WordHunterWoW_QuestEN[72965] = { title = "Aspects of Our Legacy", description = "I am proud to see that Emberthal is blossoming into a confident leader once more. Her people need her.\n\nBut that Sarkareth found Oathbinder is a reminder of the horrors of Neltharion's legacy and the folly of following him.\n\nI have a feeling that we will discover more than his trinkets and whispers here in these caverns.\n\nCome. We have much to discuss. Let us go back to Loamm and see if my brothers have found a way to subdue Fyrakk.", objectives = "" }
WordHunterWoW_QuestEN[72966] = { title = "Where There's Smoke, There's Fire", description = "If you are finished indulging Ebyssian's associate, I would have us return to more pressing matters. \n\nLocating Fyrakk is still our primary mission. We cannot continue to delay it.\n\nI have discovered a massive caldera at the western edge of Zaralek. If Fyrakk is still here, then logic dictates that this volcanic area would be his hideout.\n\nMeet us there and we will proceed.", objectives = "" }
WordHunterWoW_QuestEN[72970] = { title = "Niffen and Goliath", description = "I didn't just come all the way out here to save your sniffers, ya know!\n\nThe deepflayers are vicious and stubborn, like obsidian ore. We've tried to lead them from our town by leaving out food and such, but they're all too keen to attack our sparrow caravans.\n\nIt's the big'un ruling over them that'll be trouble. Want to pay me back? Let's you, me, and your cologne-scented friend hunt it down together. I've got the perfect bait we can use too!", objectives = "" }
WordHunterWoW_QuestEN[72972] = { title = "The Waking Shores Reverse Tour", description = "It's time to send you backwards. Not backwards in time, although we could do that, but have you fly the courses in reverse.\n\nGet ready to see these courses in a different way.\n\nLet's start with Serohs Gnikaw!\n\nWait. Waking Shores!", objectives = "" }
WordHunterWoW_QuestEN[72973] = { title = "Smells Like Loamm", description = "I smelled you weren't a bad sort from the start. A little sweaty, but not a bad sort.\n\nConsider this your personal invitation to Loamm, home of the niffen!\n\nLet's all meet just outside the entrance. That way I can give you and your pals the proper niffen welcome!", objectives = "" }
WordHunterWoW_QuestEN[72974] = { title = "Welcome to the City of Smells", description = "Ain't it incredible, uplander!\n\nNow for the backbreaking labor. We've got to deliver this deepflayer meat to all my customers and collect their pay. I'd carry it all myself, but I'm just a poor, old, frail, gorgeous woman in need now, aren't I?\n\n<Honeypelt gives you an expertly practiced wink.>\n\nWhy don't you handle it for me? Brynnsahce will do the heavy lifting while you take a little tour of the place. Put your best smell forward--we're a friendly sort!", objectives = "" }
WordHunterWoW_QuestEN[72975] = { title = "The Land Beneath", description = "I heard word you were aiding the green dragonflight, {name}.\n\nI bring word from Ebyssian.\n\nThe Life-Binder has news of the Incarnates, and she requests our presence at the Seat of the Aspects.\n\nThe black dragonflight will await you there. I will move on ahead to continue tracking our foe.", objectives = "" }
WordHunterWoW_QuestEN[72976] = { title = "A Crack in the World", description = "As you can see, Wrathion and Sabellian are also ready. If the Aspects have news of the Incarnates' actions, then the black dragonflight is prepared to answer the call.\n\nCome. They are eager to speak with us.", objectives = "" }
WordHunterWoW_QuestEN[72977] = { title = "Where the Flames Fell", description = "The Aspects have requested our help. As protectors of the Isles and dragonkind, we are more than willing.\n\nI must locate Emberthal and ask her to join. I believe I can recruit her to our cause as long as we remain committed to hers against the Sundered Flame in the future.\n\nMeet Sabellian and Wrathion at the site of the Incarnates' devastation.", objectives = "" }
WordHunterWoW_QuestEN[72978] = { title = "Scar of Earth and Fire", description = "This centaur practically attacked us upon our arrival. He seems quite protective over this burning pile of ashes.\n\nI know you have worked alongside the Shikaar before. Would you speak to him? I would like to confirm what happened here.\n\nThere is no chance that this is all a coincidence. If it connects to the Incarnates at all, we must learn all we can.", objectives = "" }
WordHunterWoW_QuestEN[72979] = { title = "The Earth Gives Way", description = "You may stay here to see what comes of this relic, or meet me afterward in Loamm. That is Honeypelt's home, which she offered us respite at while you were still in the cave.\n\nI would only ask that you check on Wrathion. He may be a ceaselessly buzzing pest, yes, but... these recent events force me to admit I care for his well-being too.  \n\nThere are only so many black dragons left. We must look out for each other.", objectives = "" }
WordHunterWoW_QuestEN[72980] = { title = "Brother's Keeper", description = "By my scales, I needed that win! That blasted Incarnate swatting us like flies did a number on my ego, and I assume Sabellian feels no different. \n\nAs infuriating as I find his lack of humor, groaning voice, and ugly shoes... I would ask that you check in on him. He is still family, after all, and I do not wish him to become dinner to these deepflayers.\n\nMeet Honeypelt and I outside these dreadful nests when you finish up with Sabellian.", objectives = "" }
WordHunterWoW_QuestEN[72981] = { title = "The Patience of Princes", description = "The centaur's report of Primalist forces pushing into the underground after Fyrakk changes the situation. Wrathion and I believe it would be a tactical mistake to dawdle here any longer, waiting for Ebyssian and his devotee to arrive.\n\nWe still wish for you to join us. If you are ready, then we three should proceed together.", objectives = "" }
WordHunterWoW_QuestEN[72982] = { title = "The Ohn'ahran Plains Reverse Tour", description = "Time to go forward to go backward once more.\n\nMore races await you in Ohn'ahran plains. Head over there now, make sure you go in the right direction.", objectives = "" }
WordHunterWoW_QuestEN[72984] = { title = "The Azure Span Reverse Tour", description = "The next set of backward courses are back in the Azure Span.\n\nWhen you're ready you should head back over there and retrace your previous steps to the previous races.", objectives = "" }
WordHunterWoW_QuestEN[72985] = { title = "The Thaldraszus Reverse Tour", description = "Once more you'll be heading back to where it all finished. Or started. I can't remember anymore.\n\nSeek out my bronze colleagues to fly the reverse courses to complete your rewinding.", objectives = "" }
WordHunterWoW_QuestEN[72987] = { title = "Here We Go Again", description = "I understand Alexstrasza's concerns. Shadowflame is a vile force that poses an indescribable threat to anyone who comes close to it, as we have personally witnessed. Unfortunately, Aberrus may contain even more threats.\n\nWe need to continue to push forward.\n\nBefore I left Zaralek Cavern, I made contact with soldiers stationed by Neltharion at the Obsidian Rest. Luckily for us, they remain loyal to the Black Dragonflight. \n\nLet us meet there.", objectives = "" }
WordHunterWoW_QuestEN[72988] = { title = "The Booty Bay Journal", description = "You will not believe who I read about today in the Booty Bay Journal. What is that look, {name}? I too enjoy light reading about world affairs. Booty Bay is fascinating!\n\nRegardless, I read about Zeros--he was once the captive of an evil mage who hated all blue dragons. He seems to have found his own way in the world since his rescue.\n\nA bit of advice for you, young one. Debt is a foolish thing to be in, especially in Booty Bay, and especially to the Baron.\n\nLet's retrieve him before the sharks do.", objectives = "" }
WordHunterWoW_QuestEN[72989] = { title = "The Ruby Hatchling", description = "An egg from the red dragonflight is ready to hatch.\n\nReport to Amella in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Ruby Oathstone to hatch in a location strong with our flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", objectives = "" }
WordHunterWoW_QuestEN[72990] = { title = "Crimson Comfort", description = "I am looking forward to our red whelp. They are, after all, my specialty!\n\nI have already spoken with Amella, and I would like to handle the nest myself. Here is a list of materials. Bring them to me when you are done, and I can fashion the most comfortable cushion you have ever seen!\n\n<Lasztak hands you a list of supplies.>", objectives = "" }
WordHunterWoW_QuestEN[72991] = { title = "Warm Dragonfruit Pie", description = "When I think of red dragon comfort food, I immediately think of the pies back at the Ruby Life Pools. You can always tell when our blacksmith, Krendisc, has downtime between orders--the entire mountain smells of delicious baked dragonfruit!\n\nMy pie may not be as good as his, but I am sure our ruby hatchling will love it. If you bring me the ingredients I will bake the best pie I can!", objectives = "" }
WordHunterWoW_QuestEN[72992] = { title = "You're Playing Wrong!", description = "Our red hatchling seems to be having quite the trouble making friends. Any time she tries to get one to play, it tends to end quickly.\n\nShe can be a bit pushy, but whelps are whelps. Why don't you get her in the right mindset to play with some tag?", objectives = "" }
WordHunterWoW_QuestEN[72993] = { title = "I'm the Boss!", description = "Never have I met such a bossy child!\n\nShe has a list. A list! Please, take Belastrasza off our claws for a bit. I just... I need to sit down.", objectives = "" }
WordHunterWoW_QuestEN[72994] = { title = "A Cavalier Pet", description = "I believe that the only way we can teach Belastrasza to be less self-obsessed is to show her firsthand how it makes others feel.\n\nVorquin are beautiful creatures, but they are incredibly high maintenance companions who need a lot of care.\n\nLysindra in Valdrakken has a baby vorquin for Bela. Perhaps she will learn through getting a taste of her own medicine.", objectives = "" }
WordHunterWoW_QuestEN[72995] = { title = "Patience, Please", description = "Belastrasza has learned much through her vorquin foal, but I have thought of one more lesson that should be excellent for her.\n\nHer lack of patience has been stumping me for quite some time. Recently I was reflecting by the water, watching the turtles go about their day. Then I was hit by a revelation!\n\nWurallie has the perfect battle to test Belastrasza's patience, but poor Princess Vorquistrasza doesn't have the endurance. Can you meet them in the Waking Shores to lend a hand?", objectives = "" }
WordHunterWoW_QuestEN[72996] = { title = "The Bronze Hatchling", description = "An egg from the bronze dragonflight is ready to hatch.\n\nReport to Xius in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Bronze Oathstone to hatch in a location strong with their flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", objectives = "" }
WordHunterWoW_QuestEN[72997] = { title = "Nothing Like a Sandy Nap", description = "While red dragons enjoy their surroundings lush and lively, bronze dragons prefer their environments dry and sandy. I am sure you can find many materials for our hatchling's nest in the Temporal Conflux in Thaldraszus.\n\nI have read that bronze whelps also enjoy an appropriately sized basin to curl themselves in. My friend at the inn in the Bronze Enclave has exclaimed often about an excess of bowls... I am sure she would not mind if we took one off her hands.", objectives = "" }
WordHunterWoW_QuestEN[72998] = { title = "Artisanal Aging", description = "I have been learning much about bronze dragons since arriving in Valdrakken. While they take their charge of time seriously, they have found many hobbies for their free time that their magic can aid them with.\n\nMy friend Gorgonzormu swears by his cheeses for all stages of dragon life. He mentioned that he has a type of parmesan that is excellent for bronze whelps. It seems that our hatchling's first meal is figured out!", objectives = "" }
WordHunterWoW_QuestEN[72999] = { title = "Here? There? Everywhere!", description = "Our bronze hatchling has been staying away from the other whelps, mostly hanging out in the sand. Sometimes we find him in the sandbox with the others, but we never see him moving around!\n\nHe could use some friendship. Why don't you treat him to a game of tag?", objectives = "" }
WordHunterWoW_QuestEN[73000] = { title = "Sneezing Through Time", description = "Zhusa is throwing us for quite the loop, {name}.\n\nSince he is so young, his control over time is not fully developed. Unfortunately, he has a strange reflex. Every time he sneezes he disappears, popping up elsewhere in any form! To top it off, he seems to have many allergies.\n\nPlease, help Zhusadormu figure out what he is allergic to so we can keep him in one place!", objectives = "" }
WordHunterWoW_QuestEN[73001] = { title = "A Scaly Pet", description = "We have been trying to decide on the perfect pet for Zhusadormu. His allergies limit our options by quite a bit, but I believe I have thought of a pet for him.\n\nI know for a fact that Zhusa is not allergic to scales. A baby hornswog is hypoallergenic and I believe Lysindra could acquire one for us.", objectives = "" }
WordHunterWoW_QuestEN[73002] = { title = "Temporal Immunity", description = "Zhusadormu has been trying hard to keep his powers in check.\n\nWhile we may not be able to prevent his allergies, he does not have to jump through time with each sneeze.\n\nWurallie believes she can test his control. Please go to the Waking Shores and help them with this lesson.", objectives = "" }
WordHunterWoW_QuestEN[73003] = { title = "The Azure Hatchling", description = "An egg from the blue dragonflight is ready to hatch.\n\nReport to Axkall in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Azure Oathstone to hatch in a location strong with our flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", objectives = "" }
WordHunterWoW_QuestEN[73004] = { title = "A Scholar's Delight", description = "Blue dragons are seekers of knowledge, even from an early age. They seem drawn to books and scrolls, finding the most comfort when surrounded by them.\n\nFor our azure hatchling, the best nest is truly amongst our many books. I request that you collect the following for his nest--a quill of his own to learn to write, something to keep him nice and cold, and a bedtime story from Azure Span. I have heard tale of one that many blue dragons remember fondly.", objectives = "" }
WordHunterWoW_QuestEN[73005] = { title = "Crystal Nutrition", description = "Yes, blue dragons eat normal food, but the most important part of their diet is magical in nature. Wherever the blue flight can be found, you can be sure there is a source of nutritious ley crystals nearby.\n\nOf course, the homelands of the blue dragons became home to many others during their absence. The brackenhide gnolls have settled in our lands with the most ley crystals and taken them for themselves. You will need to enter their camps to reclaim the crystals for our whelp.", objectives = "" }
WordHunterWoW_QuestEN[73006] = { title = "Well, Actually...", description = "As expected, our dear blue whelp is quite the little \"bookwyrm\". I knew many hatchlings just like him in Aszuna, though we only had a small collection of scrolls.\n\nWhile there are books aplenty here in Valdrakken, whelps need to get up and moving! Why don't you play some tag?", objectives = "" }
WordHunterWoW_QuestEN[73007] = { title = "New Lenses", description = "Zalethgos is a bright child, but as he has gotten older we have realized something very clear about him.\n\nHe has terrible eyesight!\n\nHe is constantly speaking of things being fuzzy and of not being able to tell where one thing ends and the next begins.\n\nThere is a salon just across the bridge in Valdrakken. Please, accompany Zalethgos to try to find him the perfect pair of glasses to aid his vision.", objectives = "" }
WordHunterWoW_QuestEN[73008] = { title = "A Scholar's Pet", description = "Long ago in Aszuna, young blue whelps from Azurewing Repose often studied magic alongside the elves of Nar'thalas Academy. I have many fond memories of the place, but one stands out among the others.\n\nThe enchanted books, while excellent to study, were quite the rascals. I have heard Lysindra acquired a similar book. I think this would be the perfect pet for Zalethgos!", objectives = "" }
WordHunterWoW_QuestEN[73009] = { title = "Sight Isn't Everything", description = "Since getting his glasses, Zalethgos has been relying heavily on his eyesight. Of course, this is normal, but he needs to remain flexible in case he loses them.\n\nI believe it is time to turn out the lights. I think Wurallie has the perfect trick.\n\nShe believes she can teach Zalethgos to find victory even when he cannot use his eyes. Please join them in the Waking Shores.", objectives = "" }
WordHunterWoW_QuestEN[73010] = { title = "The Emerald Hatchling", description = "An egg from the green dragonflight is ready to hatch.\n\nReport to Zahkrana in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Emerald Oathstone to hatch in a location strong with their flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", objectives = "" }
WordHunterWoW_QuestEN[73011] = { title = "Home Sweet Dirt", description = "Green dragons prefer a home that is both natural and mystical, imbued with the power of the Emerald Dream.\n\nThe Emerald Gardens will certainly have many materials with which to build an appropriate nest for this little one. Perhaps we should speak to a member of their flight to find something to bring them comfort as well.", objectives = "" }
WordHunterWoW_QuestEN[73012] = { title = "Hochenblume Harvest", description = "Every green dragon loves a leafy, crunchy snack. The plants that grow with Dream exposure are densely packed with nutrients, keeping the greens healthy and content.\n\nHochenblume flowers are a sweet, delightful treat for young green dragons, and contain all the vitamins that a growing hatchling needs.", objectives = "" }
WordHunterWoW_QuestEN[73013] = { title = "So... Tired...", description = "I have some worries about our new green friend. They are not sleeping as much as most green whelps tend to do.\n\nThey seem to be having trouble sleeping. Why don't you get them up and moving around with a game of tag?", objectives = "" }
WordHunterWoW_QuestEN[73014] = { title = "A Green Who Can't Sleep?", description = "{name}... we have a problem.\n\nPosidriss has insomnia.\n\nI did not even know it was possible for a green dragon to not be able to fall asleep! How are they to learn to protect the Dream if they cannot enter it?\n\nPlease, try anything you can think of to help Posidriss fall asleep.", objectives = "" }
WordHunterWoW_QuestEN[73015] = { title = "A Sleepy Pet", description = "Posidriss's sleeping troubles are still causing them many problems. This is preventing them from developing their connection to the Dream.\n\nBears hibernate, bears dream, bear cubs are soft, warm and cuddly. Some of the cubs in the Dragon Isles are even connected to the Dream. Can you fetch one from Lysindra for Posidriss?", objectives = "" }
WordHunterWoW_QuestEN[73016] = { title = "Hibernation", description = "Posidriss's companion has been helping them with their severe insomnia, but I worry that they are still falling behind other whelps in their connection to the Dream.\n\nPerhaps we can aid them through a pet battle! Green dragons often protect the Dream from the Nightmare, and Wurallie has found the perfect critter for them to practice this on.\n\nIt is mostly harmless.", objectives = "" }
WordHunterWoW_QuestEN[73017] = { title = "Stormsunder Crater Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73018] = { title = "Stormsunder Crater Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73019] = { title = "Stormsunder Crater Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73020] = { title = "Morqut Ascent", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73021] = { title = "A Lesson in Responsibility", description = "The daycare is always looking for new activities to enrich the education of the whelps.\n\nLasztak has suggested a class pet might help teach the whelps responsibility. Sir Pringly has been my personal companion for some time, and I believe his calm demeanor and sense of fun would serve the position well.\n\nSir Pringly will need his own habitat for the daycare, however. If you would gather materials, we can prepare a space just for him.", objectives = "" }
WordHunterWoW_QuestEN[73023] = { title = "Morqut Ascent - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73024] = { title = "Morqut Ascent - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73025] = { title = "Aerie Chasm Cruise", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73026] = { title = "Booty Bay", description = "Land of pirates, swindlers, and raiders! Zeros, once just a captive whelpling, has built a mighty reputation as an auction house trader in one of the most cutthroat places on Azeroth.\n\nHowever, his recent investment blunder made the front page of the Booty Bay Journal. Rescue him before his debt is collected by the Baron.", objectives = "" }
WordHunterWoW_QuestEN[73027] = { title = "Aerie Chasm Cruise - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73028] = { title = "Aerie Chasm Cruise - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73029] = { title = "Southern Reach Route", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73030] = { title = "Southern Reach Route - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73031] = { title = "Champion of the Winterpelt", description = "Thank you for all that you have done, {name}.\n\nIt is all too easy to turn within and simply continue on as you always have.\n\nThe Winterpelt will rejoin the world. We will return to the path our ancestors strayed from.\n\nAnd we will never forget your part in this.\n\nI have gathered the tribe and our new allies together to celebrate. Speak with me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[73032] = { title = "Southern Reach Route - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73033] = { title = "Caldera Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73034] = { title = "Caldera Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73035] = { title = "Path of Trust", description = "Radza sent me to find you and tell you to come to her. She set her incense burner out which means she's going to perform a ritual.\n\nThat means whatever she wants is important.\n\nRadza's just west of here. I wouldn't keep her waiting!", objectives = "" }
WordHunterWoW_QuestEN[73036] = { title = "Medicinal Fungi", description = "When we happened upon these poor souls, it was clear they were attacked by djaradin. The poison on those brutes' weapons is preventing me and their leader, Narvra, from healing them.\n\nI noticed peculiar mushrooms on some crystals nearby. I have seen their like before, and I may be able to fashion an antidote from them.\n\nCan you harvest some while Voraxian and I keep watch here?", objectives = "" }
WordHunterWoW_QuestEN[73037] = { title = "Healing Crystals", description = "Greetings! \n\nApologies if I seem... distracted. I have been beside myself worrying about my injured friends. \n\nBut maybe you, gentle{class}, can assist us?\n\nNarvra needs aid in healing us. Shards from crystal elementals have healing properties. I feel terrible asking to harm a fellow elemental, but if you could... obtain some from them, that would greatly aid my friends.\n\nDon't worry--the elementals will regenerate in time. My friends' needs come first, however impolite our gathering methods may be.", objectives = "" }
WordHunterWoW_QuestEN[73038] = { title = "A Room Without a View", description = "This vault is of Black Dragon make which means its contents are my flight's property.\n\nNormally I would have suggested we venture in together, but I was not expecting aggressive watchers. I will protect Rupert while you search for artifacts for us to examine.\n\nTo keep you safe, I will cast a spell on you I use when fighting the gronn.", objectives = "" }
WordHunterWoW_QuestEN[73039] = { title = "Restless Death", description = "What could lead someone to do this... \n\nI can perform a ritual that might aid these poor creatures passing on. Take these totems and place them along the river. With enough anchor points, I should be able to help them move on.\n\nWe'll move ahead to look for a ritual site.", objectives = "" }
WordHunterWoW_QuestEN[73040] = { title = "Bringing Disorder to Order", description = "How incredibly rude! I know we did not bring gifts, but this is hardly the way to greet visitors! There is no excuse for such terrible manners! Scoundrels! Cads! Brutes!\n\n<Rupert coughs into his hand.>\n\nWhat I meant to say was these watchers appear to be a threat. Anyone who tunnels in here could be in danger. \n\nWould you be able to make this place safer by eliminating them?", objectives = "" }
WordHunterWoW_QuestEN[73041] = { title = "Respite", description = "Thank you for everything you have done for us. \n\nWe've been able to get back on our feet now, and Butterfingers has cooked up a meal. \n\nWe lost a member of our team and everyone is still a bit shaken... We could do with the morale boost of a good meal.\n\nWould you like to join us?", objectives = "" }
WordHunterWoW_QuestEN[73042] = { title = "A Tower Yonder", description = "{name}, I... don't want to ask more of you, but could you help us finally complete our mission?\n\nWe were ordered to investigate the Gaze of Neltharion. We were defeated on our first approach, but with an escort of two dragons and the mighty {name}, I'm not as worried about the djaradin.\n\nI want us to move out soon. Could you scout out the tower first for us?", objectives = "" }
WordHunterWoW_QuestEN[73043] = { title = "A Ghastly Legacy", description = "We need to give these creatures peace.\n\nWhile you are down there assisting Voraxian, please end their suffering. Even a temporary release from this existence will help relieve their burden. In the meantime, Narvra can work on her ritual.", objectives = "" }
WordHunterWoW_QuestEN[73044] = { title = "Cataloging Horror", description = "I... I need to bring the evidence of this insanity back to my flight. It may destroy us, but my people need to know what happened here. \n\nI borrowed some cataloging cameras from Tellywin. Can you join me in documenting these atrocities?\n\nI can provide you with a similar protection to that which I gave in the vault. I will leave any fighting to you; I cannot bring myself to cause any more suffering than my flight has already wrought. \n\nLet us be done with this as swiftly as possible.", objectives = "" }
WordHunterWoW_QuestEN[73045] = { title = "Stain Removal", description = "We can begin the ritual whenever you are ready.\n\nLet's help these spirits pass on.", objectives = "" }
WordHunterWoW_QuestEN[73046] = { title = "Cavernous Capers", description = "While we wait for Veritistrasz and Narvra to nurse the rest of the camp back to health, I thought we might take a short jaunt.\n\nI sensed a cavern on our way here, and... I feel like I may need a bit of spelunking to take my mind off what just happened...\n\nFancy joining me?", objectives = "" }
WordHunterWoW_QuestEN[73047] = { title = "Terrestrial Tunneling", description = "I have to say that I am quite done with this place.\n\nWould you like to return to camp?", objectives = "" }
WordHunterWoW_QuestEN[73052] = { title = "Caldera Coaster - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73061] = { title = "Forbidden Reach Rush", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73062] = { title = "Forbidden Reach Rush - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73065] = { title = "Forbidden Reach Rush - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[73069] = { title = "Sindragosa and Malygos's Rest", description = "The preparations are now complete. Kalecgos and Alexstrasza should be here soon with the remaining essences of Sindragosa and Malygos.\n\nBoth suffered such violent ends. I heard even with his last breath, Malygos cursed Alexstrasza.\n\nAnd Sindragosa--she was slain ten thousand years ago by Nelthar... by Deathwing. Yet she was reanimated by the Lich King and slain by adventurers. I can only imagine the state this essence is in...\n\nForgive my ramblings. Kalecgos and Alexstrasza should be here shortly.", objectives = "" }
WordHunterWoW_QuestEN[73071] = { title = "A Brew for the Ages", description = "Legends speak of an ale brewed by Neltharion himself. Yet this ale has been lost to the ages! If those stories are true, and doubtless they are, we may find the recipe within this vault. \n\nIpfelkofer and I found three keys to this vault, so we decided to look around. Hopefully, our thirst for discovery will be quenched.\n\nIf we found that recipe, imagine the excitement in the brewing community! We could even feature that ale at the next Brewfest! First round will be on me.", objectives = "" }
WordHunterWoW_QuestEN[73076] = { title = "Return to the Reach", description = "Long ago, the Reach was our training ground. Now it's time to return. The island may still hold secrets from our past.\n\nScalecommander Emberthal has gone on ahead. She awaits the arrival of any who would lend us their aid. We'll need all the help we can get finding a foothold in the Reach. Safe travels.", objectives = "" }
WordHunterWoW_QuestEN[73077] = { title = "This Might Sting", description = "Relax. This Sundered Flame is merely poisoned. He won't die. Probably.\n\n He will just be in pain.\n\n<Patroclosa looks at you, then sighs.>\n\nI suppose if you wanted to spare him this fate, you could collect bile from the Quartzite Sporebats that roam this valley. It contains a natural antivenom that would ease his suffering. But I will not waste my healing magic on a murderer.\n\nAnd you may as well bring back loamshrooms, to help him keep the bile down. Though it's a kindness he doesn't deserve.", objectives = "" }
WordHunterWoW_QuestEN[73081] = { title = "Stress Fractures", description = "Another member of the Sundered Flame has been apprehended on Scalecommander Emberthal's behalf. A messenger, Amythora thinks.\n\nWe must decide what to do with him. In the meantime, it would be helpful if you could see if he has any important information.\n\nHe is well-guarded, so don't worry about him putting up a fight. Some passing Dracthyr offered their aid-- said they were companions of the Scalecommander! And they knew just how to handle Sundered Flame prisoners.", objectives = "" }
WordHunterWoW_QuestEN[73085] = { title = "Cold Feet", description = "If Marithos and Amythora want to run off and play adventurer, that's their choice. I have a sense of loyalty.\n\n<Despite his bold words, the messenger looks uncertain.>\n\nYou don't know what Sarkareth is capable of, all right?\n\nLook through my things and draw whatever conclusions you'd like. But I won't tell you anything. I can't.", objectives = "" }
WordHunterWoW_QuestEN[73086] = { title = "Healthy Competition", description = "More of my creche mates have been welcomed under Emberthal's leadership, but there are still tensions between the former Sundered Flame and the dracthyr we've hurt.\n\nFortunately, I think I've found a way to work out those tensions in a productive, dracthyrian method that will reinforce our bonds as evokers. Sparring!\n\nNow, come on. Try me! We can show all these louts how it's done.", objectives = "" }
WordHunterWoW_QuestEN[73088] = { title = "Decipher the Runes", description = "Ancient ruins?! Here?!\n\nThis ancient tablet may tell us more about who lived here. Analyze them with these handy goggles and try to find their twins amongst the rubble.", objectives = "" }
WordHunterWoW_QuestEN[73089] = { title = "What's Behind The Next Door", description = "If we're going to keep exploring these vaults, we're going to need to open more doors! And that means we'll need more keys.\n\nSee if you can find more keys around Forbidden Reach. Every door is another opportunity!", objectives = "" }
WordHunterWoW_QuestEN[73090] = { title = "Regrets in Crystal", description = "I have some idea of what Lanigosa might be doing in Crystalsong Forest, although I cannot imagine why she has taken it upon herself to do it.\n\nThat forest conceals within it the ruins of Shandaral, a former highborne settlement and the site of one of the mortal race's first clashes with the blue dragonflight. If Lanigosa truly is in Crystalsong, then it may well have something to do with Shandaral.\n\nSeek her out there, {name}, and try to convince her to return to us.", objectives = "" }
WordHunterWoW_QuestEN[73091] = { title = "Crystalsong Forest", description = "The blue dragon Lanigosa lent her aid to mortals during the most recent war against the Burning Legion. However, she failed to respond to the call of the Isles.\n\nHas something befallen her? Or has she simply chosen not to return? Whatever her reasons, Azuregos's globe seems to suggest that she was last seen in Crystalsong Forest.", objectives = "" }
WordHunterWoW_QuestEN[73092] = { title = "Something Like Family", description = "Grab a bite! Scaralesh's Special! If you're a hungry dracthyr in need of cheer, this is the place!\n\n<Scaralesh lowers his voice to talk to you.>\n\nBetween you and me, {name}? Our people have been through a lot lately. We need something to help us relax, and remind us that we've always got each other. I think a family meal could be just that.\n\nRommen and I can handle the cooking. Will you bring plates to dracthyr who need a warm bite to eat?", objectives = "" }
WordHunterWoW_QuestEN[73093] = { title = "Empty Chairs", description = "I don't want to detract from the festivities, but there's someone missing who should be here.\n\nThis is a time for all dracthyr to come together, but Rathane might not see it that way-- he was Sundered Flame, just like us. And though he left them after what happened at the Aberrus, I fear he's still grappling with the guilt. He seemed rather distressed.\n\nWould you go find him? And make sure he's alright, and that he knows he's welcome?", objectives = "" }
WordHunterWoW_QuestEN[73094] = { title = "Aiding the Expedition", description = "Sarkareth must pay for his crimes.\n\n<Emberthal steels herself.>\n\nWe cannot let any more dracthyr suffer because of Sarkareth's twisted ambitions. \n\nIf the Sundered Flame is threatening the Dragonscale Expedition, then our allies need our help.", objectives = "" }
WordHunterWoW_QuestEN[73107] = { title = "Sending Stone: Initial Report", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[73108] = { title = "Sending Stone: The Prisoner", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[73109] = { title = "Receiving Stone: Final Warning", description = "<This receiving stone still holds ancient words spoken by Neltharion in an old draconic dialect.>\n\n<The dracthyr scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[73110] = { title = "Journal Entry: Experiments", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[73113] = { title = "Journal Entry: Relics", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[73114] = { title = "Journal Entry: The Creches", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[73115] = { title = "Journal Entry: Silence", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[73119] = { title = "A Wealth of Whelp Snacks", description = "Agapanthus says there are more snack orders ready to be retrieved, but we both have our hands full.\n\nWould you run out and collect snacks while we tend the whelps?", objectives = "" }
WordHunterWoW_QuestEN[73120] = { title = "Appetizing Aftermath", description = "Today's activities were interrupted by a spontaneous food fight. This has attracted several undesirable visitors to the daycare!\n\nPlease help clean up.", objectives = "" }
WordHunterWoW_QuestEN[73124] = { title = "Hoard Behavior", description = "The whelps like to spend time with Sir Pringly, but their treading over the space has worn down his habitat.\n\nWould you retrieve another shrubbery for him? And while you are out, he could use an adorable new toy. And incense.\n\nWe cannot let his space fall into disrepair, of course.", objectives = "" }
WordHunterWoW_QuestEN[73126] = { title = "Arts and Crafts and Baths", description = "Our arts and crafts activities today have gotten well out of hand. One of the whelps enchanted their brush and the rest followed suit. Now there is a coat of paint over everything.\n\nPlease clean up the daycare while we get the paint off the whelps.", objectives = "" }
WordHunterWoW_QuestEN[73128] = { title = "Off the Page", description = "{name}, the whelps are begging us to tell them a story from their favorite anthology, but we are absolutely exhausted.\n\nThe book the whelps gravitate towards is enchanted and makes every retelling a workout.\n\nWould you mind taking over for a spell and tackle story time for us?", objectives = "" }
WordHunterWoW_QuestEN[73130] = { title = "Fowl Runic Scribblings", description = "Our magic rune lesson yesterday has apparently bled into today. The whelps are keen on practicing their runes anywhere they can, prudent or not.\n\nThis fascination has led to an interesting playtime period! Please, help us return the toys to their proper place and dispel any runes you come across.", objectives = "" }
WordHunterWoW_QuestEN[73131] = { title = "Dignified Disguises", description = "{name}! I have crafted masterful disguises for me and my friends, but there is only one way to know if they are perfect.\n\nLet's play hide and seek! Find us in Valdrakken and I will know my disguises need work!", objectives = "" }
WordHunterWoW_QuestEN[73132] = { title = "Scanning the Stacks", description = "Hi, {name}! Do you want to play a game?\n\nI have been reading about the greatest hide and seek game in all of Azeroth!\n\nI think I can improve on the strategies this book suggests. Let us play a round and test my hypothesis!", objectives = "" }
WordHunterWoW_QuestEN[73133] = { title = "Cozy Camouflage", description = "<Posidriss yawns.>\n\nI just can't sleep. Let's play a game instead!\n\nMaybe there's a comfy hiding spot out there somewhere. I bet you can't find me in the city!", objectives = "" }
WordHunterWoW_QuestEN[73134] = { title = "Eternal Escapades", description = "Ah--ACHOO!\n\nSorry. Do you want to play hide and seek? I found new places to hide and I want to play!\n\nI hope my allergies don't stir up any trouble!", objectives = "" }
WordHunterWoW_QuestEN[73135] = { title = "Obsidian Obfuscation", description = "Hi, {name}.\n\n<Ruszi looks around nervously.>\n\nDo you want to play hide and seek with me? I think it would be very good training. \n\nI need to watch out for danger, so it is good to know where to hide. Will you help me practice?", objectives = "" }
WordHunterWoW_QuestEN[73137] = { title = "Chasing the Flame", description = "\"He awaits you in the darkness\"?\n\n<Emberthal's eyes narrow.>\n\nI know where Sarkareth is.\n\nI'll need your help holding him to account. If you want, you could stay here a while and pick through these ruins, but I think we have more pressing needs at hand. If you're willing to see this through to the end, then I need you to follow me.\n\nI'm going to Dragonskull Island.", objectives = "" }
WordHunterWoW_QuestEN[73139] = { title = "Deep Sea Supplies", description = "We are accustomed to threats emerging from the sea. But there are some enemies that should never be allowed on our shores.\n\nIn the east, naga are advancing on our beaches and coves. They've brought supplies with them. If we could reduce the local naga population and seize their supplies, our chances of survival here would increase.  \n\nHere's the plan: take those supplies from their caches or their corpses, and slay their leader. Lives are on the line.", objectives = "" }
WordHunterWoW_QuestEN[73140] = { title = "Sunder the Crater", description = "The Primalists have moved into Stormsunder Crater. They're raising elementals and exploiting the land.\n\nThey should be dealt with in a swift and decisive manner. Thin their ranks. Destroy their totems. Help us make the Forbidden Reach safe for the dracthyr, the tuskarr, and all the dispossessed who want to call it home again.", objectives = "" }
WordHunterWoW_QuestEN[73141] = { title = "Everburning Embers", description = "Warmth and heat are constant concerns for us at the homestead. We don't want to burn through everything we brought, and we don't like collecting driftwood on hostile shores. Too risky!\n\nThe Primalists, though, carry some of their own fire with them.\n\nIf you could slay some powerful fire Primalists, take their Everburning Embers, and bring those embers back here, we could make good use of them.", objectives = "" }
WordHunterWoW_QuestEN[73142] = { title = "Busting Blues", description = "Malygos left behind forces to monitor us while we slept. He's gone, but his minions are still here, making life difficult for everyone.\n\nScouts have seen them using Arcane Foci. I think we could make better use of them. Go collect some. Their security forces might put up a fight, but that won't be a problem for you, will it?\n\n<Cindrethresh snorts.>\n\nMaybe they'll take the hint and leave.", objectives = "" }
WordHunterWoW_QuestEN[73151] = { title = "Hats Off", description = "", objectives = "" }
WordHunterWoW_QuestEN[73155] = { title = "The Forgotten Ring", description = "<The ring bears unusual markings. It might be of interest to one of the dracthyr at Morqut Village.>", objectives = "" }
WordHunterWoW_QuestEN[73156] = { title = "Return to Viridia", description = "I should entrust you to Viridia. She's working with the Healing Wings in Morqut Village to build a safe place for the dracthyr, the tuskarr, and our other allies in the Reach.\n\nWe have a home here... and I... I have some thinking to do. I'm grateful that you walked beside me through this trial.\n\nThis isn't over. But at least I know that the next time we face Sarkareth, we can count on you. Thank you.", objectives = "" }
WordHunterWoW_QuestEN[73157] = { title = "Wings of Mercy", description = "With the lifting of the storms, we dispatched scout teams to explore the island. \n\nSeveral of our teams have not returned. We fear they may have fallen to unknown dangers.\n\nCan you search the island for them? Once you locate them, use the Mender's Signal to summon a medic.", objectives = "" }
WordHunterWoW_QuestEN[73159] = { title = "Exploring Our Past", description = "With your help, we can now delve deeper into the secrets of this land.\n\nNearby lay the Zskera Vaults. Within these large underground chambers, Neltharion stored various treasures and forgotten research. Exploring these vaults would be most beneficial.\n\nPlease travel with Tacha and Jeb and assist them as needed.", objectives = "" }
WordHunterWoW_QuestEN[73160] = { title = "Helping Hand and Claw", description = "Members of the Dragonscale Expedition traveled here to help explore ruins on this island. Their efforts may help us uncover more details about our past.\n\nMy scouts have spotted three of them shipwrecked on Sharpscale Coast. See if you can help them reach the village safely.", objectives = "" }
WordHunterWoW_QuestEN[73169] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Stormwind at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[73170] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Orgrimmar at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[73171] = { title = "Gain New Look: Maiev", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "" }
WordHunterWoW_QuestEN[73172] = { title = "Shikaar Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[73173] = { title = "Gain Even Newer Look: Maiev", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "" }
WordHunterWoW_QuestEN[73174] = { title = "Gain New Look: Sneed", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "" }
WordHunterWoW_QuestEN[73175] = { title = "Gain Even Newer Look: Sneed", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "" }
WordHunterWoW_QuestEN[73178] = { title = "Hands Off Our Booty!", description = "The Irontide Pirates have been stealing from dracthyr and tuskarr. They're taking anything and everything. It's all just booty to them!\n\nYou should recover our stolen goods. Make them regret coming here.", objectives = "" }
WordHunterWoW_QuestEN[73179] = { title = "Soupocalypse Now!", description = "The Irontide pirates think they can sail in and take over the islands. They clearly have no idea who they are dealing with. Our Morqut friends will provide you with the transportation. We dracthyr will provide the... munitions.\n\n<Cindrethresh smirks.>\n\nFusethrian has been trying to learn to cook the tuskarr way with mixed results. Ask him for his more volatile attempts. We can get some safe disposal and run off these pirates in one go!", objectives = "" }
WordHunterWoW_QuestEN[73181] = { title = "Zeroing Debt", description = "I do hope that is the last we see of the Baron. Truth be told, I respect his seat of power in Stranglethorn.\n\nWe were lucky to find Zeros still alive. He must have developed quite the positive relationship with the Baron before all this nonsense, or else he would not have been given so much time.\n\nLet us return to the Archives.", objectives = "" }
WordHunterWoW_QuestEN[73183] = { title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", objectives = "" }
WordHunterWoW_QuestEN[73188] = { title = "The Sullied Banner", description = "So long as there has been magic, there have been those willing to utilize it for nefarious ends.\n\nI am not certain what grievances these rogue mages hold that has prompted Surigosa to chase them down, but I am inclined to trust her judgment on the matter. Let us go to her, {name}; perhaps we can solve this rogue mage problem and convince Surigosa to return in a single turn.", objectives = "" }
WordHunterWoW_QuestEN[73189] = { title = "Creche Cache", description = "I'm glad you're here. Beetles infected our support creche, so we evacuated in a hurry. That meant leaving a lot of supplies behind.\n\nNow we've got a lot of injured explorers, and we could sure use those supplies. Can you help us?\n\nWe need you to retrieve as many as you can. Just don't let the toxins get to you.", objectives = "" }
WordHunterWoW_QuestEN[73190] = { title = "Toxic Infestation", description = "The Healing Wings need access to our support creche, but it's still overflowing with an infestation of toxic beetles.\n\nI'm sure Viridia would appreciate it if we helped exterminate those pests.", objectives = "" }
WordHunterWoW_QuestEN[73191] = { title = "Snake Wrangling", description = "The same toxins that plague our Support Creche are seeping into migrating watersnakes.\n\nWe need to relocate the snakes back to their original pools. If we don't, that invasive species is going to wreak havoc on the environment.\n\nI can loan you a friendly water elemental to help you transport the snakes. It's for our own safety as much as theirs.", objectives = "" }
WordHunterWoW_QuestEN[73192] = { title = "Feathered Fiend", description = "The trinket appears to be some sort of Noblegarden decoration. It should probably be returned to the festivities in Goldshire.", objectives = "" }
WordHunterWoW_QuestEN[73194] = { title = "Up Close and Personal", description = "The great proto-dragons are some of the fiercest creatures to roam the Forbidden Reach.\n\nTaking them down isn't easy, but we have many weapons in our arsenal.\n\nTake this spear and harpoon. You'll need them. If you get caught in a proto-drake's maw, you'll need to fight tooth and claw with everything you've got to survive.\n\nIt isn't easy, but I know you can do this.", objectives = "" }
WordHunterWoW_QuestEN[73196] = { title = "Tarecgosa's Rest", description = "{name}, hold a moment.\n\nBefore you leave... I have one more thing that needs to be done. There is one last member of my kin that deserves rest.", objectives = "" }
WordHunterWoW_QuestEN[73197] = { title = "Love Unending", description = "Alongside a proper conduit to house Tarecgosa's soul during the ritual, we need enough magical essence to ground the flower. The bronze dragonflight was involved in creating the staff you hold, so I believe it best we use their magic again.\n\nSome of the sand within the Temporal Conflux should suit this purpose perfectly. Just make sure it's of the more magical variety.", objectives = "" }
WordHunterWoW_QuestEN[73198] = { title = "Forget Her Not", description = "The staff was made with the bough of a world tree, so the receptacle that the soul is transferred to needs to be comparable. Within the adverse conditions of Vakthros there may be a flower that is tenacious enough to grow.\n\nHowever, it will be fragile given the circumstances. Find it, and then bring it to one of the green dragonflight's groves to help strengthen it.", objectives = "" }
WordHunterWoW_QuestEN[73199] = { title = "Rhapsody in Blue", description = "It is time. I cannot delay this any longer.\n\nLet us say our farewells.", objectives = "" }
WordHunterWoW_QuestEN[73226] = { title = "Dragonskull Shoal", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "" }
WordHunterWoW_QuestEN[73227] = { title = "Jade Forest", description = "Daughter of Malygos and Saragosa, Kirygosa survived the turbulent Nexus War that ripped away her life and family.\n\nAfterwards, Kirygosa sought a permanent summer in Stranglethorn. Finding warmth but not quite peace, she moved on to Dawn's Blossom, a small village nestled in the Jade Forest.\n\nThe blue dragonflight would welcome her return.", objectives = "" }
WordHunterWoW_QuestEN[73371] = { title = "Gain New Look: Night Elf Huntress", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "" }
WordHunterWoW_QuestEN[73372] = { title = "Gain Even Newer Look: Night Elf Huntress", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "" }
WordHunterWoW_QuestEN[73386] = { title = "Gain New Look: Stonehoof Tauren", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "" }
WordHunterWoW_QuestEN[73387] = { title = "Gain Even Newer Look: Stonehoof Tauren", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "" }
WordHunterWoW_QuestEN[73388] = { title = "Gain New Look: Undead Ghoul", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "" }
WordHunterWoW_QuestEN[73389] = { title = "Gain New Look: Murloc", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "" }
WordHunterWoW_QuestEN[73390] = { title = "Gain New Look: Whelp Egg", description = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", objectives = "" }
WordHunterWoW_QuestEN[73391] = { title = "Gain Even Newer Look: Undead Ghoul", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "" }
WordHunterWoW_QuestEN[73392] = { title = "Gain Even Newer Look: Murloc", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "" }
WordHunterWoW_QuestEN[73393] = { title = "Gain Even Newer Look: Whelp Egg", description = "Apply a another Rumble Foil to your Warcraft Rumble Mini and gain an even NEWER look!", objectives = "" }
WordHunterWoW_QuestEN[73398] = { title = "Too Far Forward", description = "Our forward forces pressed too aggressively into a Sundered Flame stronghold. Now they need help. We really need to send you in to extract them.\n\nHelp them get out of there. You can use your own magic or these healing draughts from Viridia. And while you're there? Put some hurt on the Sundered Flame. They certainly deserve it.", objectives = "" }
WordHunterWoW_QuestEN[73399] = { title = "The Search for Blue Dragons", description = "Thank you for your help so far, {name}. We've still got more blue dragons to track down.\n\nI'll give you the honors of choosing where to go next.", objectives = "" }
WordHunterWoW_QuestEN[73404] = { title = "Lost Blue Dragons", description = "The Azure Archives are starting to feel much more lively, thanks to your help.\n\nChoose which location you'd like to investigate next.", objectives = "" }
WordHunterWoW_QuestEN[73405] = { title = "A Pair of Blue Dragons", description = "I appreciate your aid so far, {name}. \n\nWhere would you like to look next?", objectives = "" }
WordHunterWoW_QuestEN[73406] = { title = "The Last Missing Blue Dragon", description = "We've only one more blue dragon to locate now, {name}.\n\nLet's finish this, shall we?", objectives = "" }
WordHunterWoW_QuestEN[73550] = { title = "Honeyfreeze Mead", description = "Right, so now that we've established somewhat friendlier relations and learned a wee bit of Winterpelt, it's about time tae make friends in the proper dwarf manner.\n\nWhat gesture of friendship is better than a stiff drink tae ward off tae cold? Both dwarves and furbolgs have a long history of brewin', so we can call it somethin' of a cultural exchange too!\n\nI saw some hearty lookin' bees a bit south of here. And where there's bees, there's honey. And where there's honey, there could be mead.", objectives = "" }
WordHunterWoW_QuestEN[73692] = { title = "Hive Maintenance", description = "It wouldn't do tae steal a hive's honey without ensurin' they have enough food tae make it through the cold. Especially if we might want more down the line.\n\nFrostbell pollen's sticky stuff an' a wee bit fragile. But if ye run through some of the bloomin' plants, it'll be on ye like fleas on a kobold.\n\nThen, all ye have to do is bring it back tae a bee afore it blows away--they'll lick it right off ye! Tickles a bit too!", objectives = "" }
WordHunterWoW_QuestEN[73694] = { title = "Stuck in Stasis", description = "When the first dracthyr awakened from millennia of slumber, we left the Forbidden Reach for the Dragon Isles. Yet not all of the dracthyr are free. Some are still in stasis, hidden deep within their creches.\n\nWe need your help. Travel to Froststone Vault. See if you can find more of our friends. One of my Healing Wings would be glad to accompany you. Choose someone who best suits your need.\n\nIt is time for all dracthyr to rejoin the world as we have.", objectives = "" }
WordHunterWoW_QuestEN[73703] = { title = "A Summon to Orgrimmar", description = "{name}, Eitrigg has requested your presence in Grommash Hold. \n\nHe seemed like he had much to tell you.", objectives = "" }
WordHunterWoW_QuestEN[73704] = { title = "Local Flavors", description = "Now that we have the base o' the brew figured out, we need tae add the spice.\n\nPut that rudimentary Winterpelt I taught ye tae use and ask around for local ingredients tae blend into the flavor profile. Try talkin' with Kazzi. From what I gather she's somethin' of a trader. \n\nThe finished brew will be a mix of dwarven and Winterpelt traditions which seems appropriate for the circumstances.\n\nAn' if we're lucky, it won't taste half bad!", objectives = "" }
WordHunterWoW_QuestEN[73707] = { title = "TICKET: Glimmerogg Games", description = "<Written in sloppy handwriting that makes it almost impossible to read.>\n\nCONGRATULATIONS, LOAMM VISITOR! YOU'VE FOUND A TICKET TO THE BEST COMPETITION IN ZARALEK CAVERN: THE GLIMMEROGG GAMES!\n\nYou'll find the games in the south of Zaralek Cavern. Just look for a bunch of happy drogbar! Don't miss our fun activities like...\n\n<The rest of the page is illegible except for the name \"Brogg.\">", objectives = "" }
WordHunterWoW_QuestEN[73708] = { title = "Pay to Play", description = "It doesn't matter if you were invited or if you just showed up. Drogbar, niffen, or {race}, everyone pays for the Glimmerogg Games! \n\nEven I did, and I'm runnin' this show!\n\n<Brogg points aggressively to a ticket of his own.>\n\nI know you can't pay in drogdollars, but you can pay in snacks for everyone. And we love mushrooms and fish! Bring Brogg some food, and we're square, okay?", objectives = "" }
WordHunterWoW_QuestEN[73709] = { title = "Favor on the Side", description = "Brogg counts more people than fees today. It's not sitting well with me neither. I'm gonna blow my top!\n\nSure, Glimmerogg is popular, but it's not all fun and games. We have rules and everyone must follow them.\n\nYou look like someone who can read fine print and follow rules. If you get rid of the intruders that are cheating Brogg, I may have something for you.", objectives = "" }
WordHunterWoW_QuestEN[73710] = { title = "Rock By Rock", description = "Ah, a challenger! So, you think you can defeat Storul Heavystone in his famous rock-lifting marathon challenge? \n\nHA! Silly uplander. No one can compare to Storul! No one has EVER matched my strength.\n\nBut maybe you try. Defeat will teach you a valuable lesson: true strength comes from struggle!\n\nOr, Storul will have a new friend to spot him at the gym! Get it, brul!", objectives = "" }
WordHunterWoW_QuestEN[73711] = { title = "Marked Champion", description = "You did good on Storul's challenge, but that does not make you a champion like him.\n\nTo get on my level, you have to lift the greatest rock--not a real rock, a spirit one.\n\nYou must face what every drogbar fears... and venerates! You must be blessed by the Carcaxas, The Great Daughter-Worm.\n\nBut Carcaxas only bestow her mark on those who are DETERMINED and don't FEAR SMELLING BAD!\n\nAre you ready to take on this challenge? CAN YOU DO IT, BRUL!?", objectives = "" }
WordHunterWoW_QuestEN[73715] = { title = "Driftwood Derby", description = "One of the challenges of any new village is finding enough raw building materials. Fortunately, the ocean often brings us exactly what we need.\n\nTake my boat and sail around the island. Along the way, you can collect driftwood in nets. But be wary. You may attract some unwanted attention!", objectives = "" }
WordHunterWoW_QuestEN[73716] = { title = "Aylaag Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[73717] = { title = "Ohn'ir Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[73848] = { title = "Iskaara Elder Shomkol", description = "", objectives = "" }
WordHunterWoW_QuestEN[73858] = { title = "Iskaara Elder Nemaglek", description = "", objectives = "" }
WordHunterWoW_QuestEN[73859] = { title = "Iskaara Elder Sik'ek", description = "", objectives = "" }
WordHunterWoW_QuestEN[73860] = { title = "Elder Dekidig", description = "", objectives = "" }
WordHunterWoW_QuestEN[73861] = { title = "Elder Razlok", description = "", objectives = "" }
WordHunterWoW_QuestEN[74117] = { title = "Rare Prey", description = "Rare and dangerous creatures lurk around the creches of the Forbidden Reach. If you and your allies want to stay safe, you should hunt down these threats.", objectives = "" }
WordHunterWoW_QuestEN[74118] = { title = "Spelunking the Den", description = "Did you have a chance to visit the Skyfox Den? A very exciting place, from what I've heard. Expedition's spelunkers started surveying the cave and even installed a few grappling hooks on the ceiling, but they were scared away by violent slyverns.\n\nCan you do me a favor? Get inside the Skyfox Den, grab the abandoned gear, and check the ceiling for any hidden crevices. Who knows what could be hidden inside?", objectives = "" }
WordHunterWoW_QuestEN[74119] = { title = "Angler's Challenge", description = "Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots to cast a line. \n\nWhy don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.", objectives = "" }
WordHunterWoW_QuestEN[74282] = { title = "Authentic Authorization", description = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course!\n\nIf I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans!\n\nIf you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", objectives = "" }
WordHunterWoW_QuestEN[74291] = { title = "Blue is My Favorite Color", description = "Oh, Kiry's here! I wonder if she has made her decision.\n\nPlease ask her for thoughts, {name}.", objectives = "" }
WordHunterWoW_QuestEN[74293] = { title = "Not Forgotten", description = "Viridia is confident that more dracthyr may slumber in these chambers, long forgotten amongst Neltharion's relics.", objectives = "" }
WordHunterWoW_QuestEN[74294] = { title = "The Keys You Need", description = "Can I trust you? These are the only keys we have. If we lose them, we can't open any locked doors.\n\nHere. Take them. Use them on the doors within this chamber. You look like a hero. Be bold! Throw those doors wide! You'll find glory or... um... something that is not glory but is still amazing! Just don't die.\n\nWe might find more, but we'll have to search the island to find them.", objectives = "" }
WordHunterWoW_QuestEN[74334] = { title = "Future Aspects", description = "My brothers are not interested in investigating the Sundered Flame or helping Emberthal. \n\nIt worries me that we are dividing our efforts, but I understand their motivation in considering our next steps against Fyrakk immediately.\n\nI will aid Emberthal as I promised, but perhaps we should ask for help from the local niffen...", objectives = "" }
WordHunterWoW_QuestEN[74335] = { title = "A Moment of Reflection", description = "I do not understand what would drive Turi Flickerflame and her band of mages to attempt what they have done here today. But I do understand the pain of losing family. I understand the fear and regret that follows you wherever you go.\n\nI have much to think about. I imagine Kalecgos has much yet to do in the Dragon Isles--return there with him. I will follow soon... I need some time to think upon what happened here today.", objectives = "" }
WordHunterWoW_QuestEN[74354] = { title = "Artifacts Abound", description = "It is... certainly bizarre to see Sindragosa, real in all but the flesh.\n\nLook, I appreciate that you have both come all this way for me. The Isles sounds delightful, but I have dedicated many years to cleaning up Winterspring. I am not about to leave a job unfinished. Magic is abound and unfortunately not all good.\n\nIf you would like to help, The Hidden Grove is next on my list. Therein lie ruins of totems that still emanate with some sort of magic. Will you collect pieces of them?", objectives = "" }
WordHunterWoW_QuestEN[74355] = { title = "Primordial Embellishment", description = "How remarkable! You can affix such a variety of special gems to enhance its power!\n\nYou should journey back into the Zskera Vaults and locate a Primordial Jeweler's Kit. Yes, that's what you'll need.\n\nCrafting gems of this type requires specialized tools. Once we have them, we can fully explore the ring's power! The mind reels with limitless possibilities...", objectives = "" }
WordHunterWoW_QuestEN[74356] = { title = "Back with the Blues", description = "It seems I had a good idea.\n\nNow let us hope we can broach the subject of the Isles again. I am glad to see Haleh relaxed. She deserves it.", objectives = "" }
WordHunterWoW_QuestEN[74359] = { title = "Plunder Siege", description = "We're not the only ones to have noticed the storms abating over the Forbidden Reach. \n\nOther interested parties have arrived too, looting everything they can and storing their spoils in chests. If they use Neltharion's old hoard chests, they're in for a surprise when the chests' enchantments lock them out. We'll need to clear out surrounding looters to break the chests' enchantments.\n\nSee if you can recover a stolen item, specifically my old journal. It's nowhere to be found.", objectives = "" }
WordHunterWoW_QuestEN[74374] = { title = "An Important Heirloom", description = "I can guide you in crafting your offering to the ancestors, but you will need two things:\n\nFirst, you need to know the basics! Arugi here can teach you how to cook if you don't already know.\n\nSecond, I need my old cookbook. We're going to make something truly special, a fusion of old Draenor and Azeroth, and I'm going to need it for reference. \n\nGo fetch my book from the inn, and we can get started.", objectives = "" }
WordHunterWoW_QuestEN[74375] = { title = "Collating Their Research", description = "It no longer matters how the Sundered Flame got here; now we need to know why. What is in this vault that Sarkareth is after?\n\n{name}, while you are in their camp, look for notes, research papers, journals--anything you can find that might reveal their intentions. Please bring whatever you find to me.", objectives = "" }
WordHunterWoW_QuestEN[74376] = { title = "Coalesced Storm Remnants", description = "The Primalist Researchers in the area will be interested in this for further study.", objectives = "" }
WordHunterWoW_QuestEN[74379] = { title = "Still Within Reach", description = "While we dracthyr were kept in stasis, the Spellsworn, ancient servants of Malygos the Spellweaver, were our wardens. However, despite being slain years ago, the late Aspect's forces are still loyal to him and his lasting directive to keep this island contained. They present a danger to any dracthyr still lost, wounded, or otherwise unaccounted for.\n\nScouts have reported the sighting of a rather large Spellsworn brute hunting for escaped dracthyr. This deadly pursuer must be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[74381] = { title = "Hidden Legacies", description = "Raszageth and her storms are gone, but our troubles are far from over.\n\nThe way to the Reach is clear again, and some of our allies have returned to establish a base camp. However, Sarkareth and the Sundered Flame have begun making their way there as well.\n\nWe need to secure the island. We would appreciate your aid.", objectives = "" }
WordHunterWoW_QuestEN[74389] = { title = "Filming the Caldera", description = "The arthropods in Caldera of the Menders are truly vicious. One of our gyrocopters went missing there!\n\nOur expedition sent a unmanned surveillance aircraft there, but it hasn't returned. Can you find the gyrocopter? You could use it to capture the Caldera's wildlife on camera?", objectives = "" }
WordHunterWoW_QuestEN[74390] = { title = "Brutal Prey", description = "This land is crawling with opportunities for a skilled hunter. We want you to join the hunt. \n\nSome threats are feral. Dare I say it, some are greatest threats are sentient and malevolent. If we all work together, we can make the Reach a safe haven, as it used to be.", objectives = "" }
WordHunterWoW_QuestEN[74391] = { title = "Harpooner's Challenge", description = "Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots.\n\nWhy don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.", objectives = "" }
WordHunterWoW_QuestEN[74393] = { title = "Report: Battlefield Ruins", description = "Our situation is worse than we thought. \n\nTheir dominance of the air keeps us at a disadvantage. They plan on freeing their powerful Elder from Aberrus. Allowing them to accomplish this could result in us permanently forfeiting control of this area.\n\nSeek out Field Commander Ignax in the Battlefield Ruins and see what can be done to turn the tide of this battle. We will join you shortly.", objectives = "" }
WordHunterWoW_QuestEN[74415] = { title = "A Worthy Offering", description = "Now that we have everything on the list, you just have to put it all together, right? How hard could it be?\n\nUmm... I'm going to let you handle it, though. I'll watch.\n\n<Cooking Recipes can be found under Orcish Cuisine in Classic Cooking.>", objectives = "" }
WordHunterWoW_QuestEN[74433] = { title = "Returning the Blade", description = "<This dagger, found buried in the chest of the giant worm Icebreaker, belonged to Saza. It is evident that Saza fought bravely, deeply wounding the monster before her death.\n\nThis blade should be brought back to the village to give her clan closure.>", objectives = "" }
WordHunterWoW_QuestEN[74436] = { title = "Storm Warning", description = "Ah, {class}! I knew I would find you at the right place at the right time. \n\nThe elements do not just threaten the Dragon Isles in our current time, but also from beyond. Go to the Temporal Conflux and travel through the rift into the future the primalists have overrun.\n\nThere, speak to Soridormi. She will have more details for you when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[74437] = { title = "Resisting the Storm", description = "The Primalists are growing in strength in this future timeline, despite our best efforts. If they overrun this valley and threaten the Temporal Conflux, they may become a problem for the rest of the timeways.\n\nWe are already protecting the timeways from enough threats.\n\nPush back on them, {name}. We need to keep this peril in check. Speak to Tarnormu to gather any supplies you might need.", objectives = "" }
WordHunterWoW_QuestEN[74442] = { title = "One Dragon's Junk...", description = "Greetings! I am looking for items of power from my flight's past. \n\nWe have a history of great warriors and battle prowess, and I want to recover items that will help us reach that again.\n\nI heard you found these vaults. If you see anything of interest inside, could you show it to me?", objectives = "" }
WordHunterWoW_QuestEN[74443] = { title = "Is Another Dragon's Treasure?", description = "I must admit, I am out of my depth here. \n\nIt is of black dragon make. The decoration on the pommel matches, but I have no idea what it is. Which I suppose is the point.\n\nI have heard you have travelled the Isles. Do you have any recommendations on who to talk to?", objectives = "" }
WordHunterWoW_QuestEN[74447] = { title = "Verbal Archaeology", description = "Where should we meet this Veritistrasz of yours?\n\nRuby Lifeshrine? Are you sure this is not an attempt to introduce me to Alexstrasza? \n\nNo? Well then! I shall meet you at the Ruby Lifeshrine!", objectives = "" }
WordHunterWoW_QuestEN[74476] = { title = "Slime Dies When You're Having Fun", description = "The investigators here told me that there were some side effects to removing the time anomaly from Eon's Fringe. Seems a bunch of slimes snuck through the timestream in the process. \n\nOh! Oh! Time slimes! They're time slimes! Ha.\n\nAnyway, could you take some of them out?", objectives = "" }
WordHunterWoW_QuestEN[74488] = { title = "Runaway Rusziona", description = "Black whelps have the agility of a rock, but they try to make up for it with the most impressive top speed. Try to take it easy around those corners!\n\n[Eruption]: Dash forward.\n[Rock Halt]: Stops forward movement.\n[Earthen Will]: Restores all Vigor. Must be grounded.", objectives = "" }
WordHunterWoW_QuestEN[74489] = { title = "Zhoomsa", description = "Bronze whelps can be careless when trying to win, so be careful with the timeways!\n\n[Growth Spurt]: Transform into an adult and gain improved speed.\n[Bedtime Rewind]: Restore 1 Vigor until all Vigor has been recovered.\n[Sacred Timeline]: Resets cooldowns.", objectives = "" }
WordHunterWoW_QuestEN[74490] = { title = "Zaleth on the Go", description = "Blue whelps will try to skip ahead where they can, but be careful blinking through rings!\n\n[Blink Boost]: Blink forward and dash.\n[Arcane Acceleration]: Increases forward acceleration.\n[Accelerated Restoration]: Consumes Arcane Acceleration and restores Vigor.", objectives = "" }
WordHunterWoW_QuestEN[74491] = { title = "Pole Position Posidriss", description = "Green whelps have an affinity for short naps and bursts of speed, so do your best to keep pace.\n\n[Nature's Wind]: Fly up then restore 1 Vigor.\n[Emerald Restraint]: Adds 5 sec to Winds of Life's duration.\n[Winds of Life]: Anytime you restore Vigor, dash forward.", objectives = "" }
WordHunterWoW_QuestEN[74492] = { title = "Blistering Belastrasza", description = "Red whelps can be a little out of control, so best of luck!\n\n[Ruby Exhaustion]: Consumes all Vigor over time.\n[Crimson Flight]: Restore all Vigor, boosting forward each time.\n[Renewal]: Consumes Crimson Flight, resets cooldowns.", objectives = "" }
WordHunterWoW_QuestEN[74493] = { title = "Second Time Is The Charm", description = "<Voraxian bounces the Odd Round Object in his hands a few times.>\n\nHmm, it lands in the hand well, like it was made for this. Let us talk to Veritistrasz and see if he knows more.", objectives = "" }
WordHunterWoW_QuestEN[74494] = { title = "A Scale for a Scale", description = "The elder waking was a threat, certainly. But there is one more mission I must complete before we depart, lest we lose our only chance to complete it at all.\n\nHowever different the Zaqali tribe may be from the Qalashi, they are still dragonslayers. Their implements of war are no less deadly to our kind.\n\nI need a spear on par with the one we saw at the elder's side. Find the largest one you can and deliver it to me.", objectives = "" }
WordHunterWoW_QuestEN[74495] = { title = "The Tale of Hraxian", description = "Hello {name}, it is good to see you.\n\nWould you like to join us around the fire? I think it is time we heard a positive story about the obsidian flight of old.\n\nI once promised yourself and Voraxian I would tell you the story from the vase you found in the Zskera Vaults. I believe it is that time.", objectives = "" }
WordHunterWoW_QuestEN[74502] = { title = "Complimentary Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[74514] = { title = "The Slowest Fan Club", description = "Has a crowd ever roared for you? Everyone shouting your name, pushing you on to victory? \n\nI want to give that same feeling to Slick. Give him the taste of being a champion.\n\nCourse, we don't speak snail, so we can only be so useful. Round up some snails that could use purpose in their lives. Slick needs a fan club.", objectives = "" }
WordHunterWoW_QuestEN[74515] = { title = "Snail Mail", description = "Racing snails are all about speed, but riding snails? They need stamina to boot.\n\nI owe some supplies to a buddy in Loamm. Why don't you make the delivery for me? Help build Slick's endurance.\n\nOh, and make sure you don't dismount. Not much of a training session if you keep hopping off and on.", objectives = "" }
WordHunterWoW_QuestEN[74516] = { title = "A Snail's Pace", description = "It's an off day for our local racing track, so I figured we could take the opportunity to build up Slick's speed. Grow some confidence on his home turf, I'm thinking.\n\nTake two laps around the track. Let's see how your training is coming along!", objectives = "" }
WordHunterWoW_QuestEN[74517] = { title = "All Terrain Snail", description = "While life in these caverns is plenty exciting, Slick has a future in the world above. Namely as your trusty mount. \n\nWhich means he needs to prepare for all sorts of environments.\n\nLuckily, the Dragon Isles has biomes to spare. Why don't you take him for a spin? Give him a taste of what's to come. One lap per location should do the trick.", objectives = "" }
WordHunterWoW_QuestEN[74518] = { title = "Resistance Training", description = "These caverns aren't easy on my poor snails, which is why I feed them a special crystal diet. Keeps their shells hard and gleaming. \n\nSlick eats more than his fair share though, so I'm plumb out. \n\nWould you collect some crystals in Zaralek Cavern? Get a nice mix, too. We need to make sure Slicks ready for every environment.", objectives = "" }
WordHunterWoW_QuestEN[74519] = { title = "Good for Goo", description = "Every snail trainer knows that it's all about the goo. The slime. The mucus. That's how you turn a speedy snail into a champion.\n\nSlick could use a good slather. Go out and collect some goo from the local slime trails to slick him up. Heh.", objectives = "" }
WordHunterWoW_QuestEN[74520] = { title = "Less Cargo", description = "Those djaradin think they own these caverns, coming around here and looting our supplies. How am I supposed to train champions under these conditions?\n\nCan you do me a favor and get those supplies back? I can't help you train Slick without them. \n\nBesides, the big fellow could use a rest day.", objectives = "" }
WordHunterWoW_QuestEN[74521] = { title = "A Flame, Extinguished", description = "Sarkareth is no more.\n\nHis hubris left him vulnerable to the dark influences that have assaulted our flight for millennia. Just like Neltharion before him.\n\nI believe Emberthal seeks more answers than what Wrathion and Sabellian are able to give. She may need some assistance.", objectives = "" }
WordHunterWoW_QuestEN[74522] = { title = "Remnants", description = "Some call me a miracle, you know. Yet my birth was anything but natural. I was crafted, much as the creatures in here were crafted. Many died painful, tragic deaths so that I could live.\n\nThis... callousness towards the living is something I wish to eradicate.\n\nTake this, and use it to destroy any intact specimen tanks we encounter. Nothing deserves to suffer like this.", objectives = "" }
WordHunterWoW_QuestEN[74523] = { title = "A Traitor's Due", description = "These sycophants shame themselves and the black dragonflight. It is clear that they are willing to die in service of my father's dark machinations.\n\nLet us not disappoint them.", objectives = "" }
WordHunterWoW_QuestEN[74525] = { title = "Honorbound", description = "<The djaradin's body is gaunt and wasted, its life energy siphoned away by the hungry machines that power this dark laboratory.\n\nPerhaps there are other djaradin imprisoned here that can be spared from this horror.>", objectives = "" }
WordHunterWoW_QuestEN[74538] = { title = "Blow It Up", description = "Make no mistake, the djaradin are experienced dragon killers. But right now their ruthless tactics are overshadowed by the devastating power of their battlefield ballistae, capable of taking out any threat from a long distance. \n\nI have lost many good soldiers to these potent weapons.\n\nIt is essential that we destroy the ballistae if we hope to level the playing field and take to the skies. It is possible that we may even be able to gain the upper hand in this war.", objectives = "" }
WordHunterWoW_QuestEN[74539] = { title = "Thinning Their Defenses", description = "The Firecallers are a formidable force. Their powerful, lethal magic allows them to vaporize anything that comes near them.\n\nTheir strategic positioning on high ledges makes them difficult to reach, but we cannot allow them to continue causing destruction among our forces.\n\nThe fate of our forces depends on your success. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[74540] = { title = "Intercepting Communications", description = "{name}, we need intel, and we need it now.\n\nSomewhere within one of the djaradin's encampments, you will find their field general. He is a seasoned and formidable opponent, responsible for many attacks on our forces. \n\nAccording to our field agents, he may possess crucial military orders outlining their next offense and the locations of their new supply lines.\n\nIt is imperative that we obtain these orders. We cannot allow the djaradin to gain the upper hand.", objectives = "" }
WordHunterWoW_QuestEN[74542] = { title = "Air Superiority", description = "<As Ignax looks up, you see a small smile appear on his face.>\n\nFew of my soldiers have experience fighting alongside dragons. What a glorious day.\n\nTheir presence gives us confidence, {class}. Now we must put an end to the djaradin's advance once and for all.", objectives = "" }
WordHunterWoW_QuestEN[74557] = { title = "Investigating the Unknown", description = "We can only assume that something ambushed the marching djaradin. Who could have done this? \n\nWe should investigate it before we proceed.", objectives = "" }
WordHunterWoW_QuestEN[74562] = { title = "Break Them Out", description = "Cages, chains and transportation carts... I think we all know where this leads.\n\nIf the drakonids plan on capturing and enslaving the slitherdrakes, then they are no better than the djaradin. \n\nSee what you can do to thwart their plans.", objectives = "" }
WordHunterWoW_QuestEN[74563] = { title = "Worst of the Worst", description = "Everything here suggests this is a well-coordinated effort. These slitherdrakes are almost like wild beasts. They will not stand a chance without our aid.\n\nFind whoever is leading their operation and put an end to this.", objectives = "" }
WordHunterWoW_QuestEN[74568] = { title = "They Who Would Burn Us", description = "The djaradin and their Primalist allies are a stain upon the land, {name}.\n\nWipe them from it.", objectives = "" }
WordHunterWoW_QuestEN[74569] = { title = "Deny Them Resources", description = "This entire invasion has been carried out with the sole objective of infusing raw materials with elemental power on an unprecedented scale.\n\nWhile we may not know Fyrakk's ultimate goal, frustrating his efforts seems straightforward enough.\n\nIf he wants these materials, we will deny them to him.", objectives = "" }
WordHunterWoW_QuestEN[74570] = { title = "Aid Our Wounded", description = "{name}, our forces were not prepared for such an onslaught.\n\nThese djaradin fight with more furor than the forces we have faced in the past. We have wounded behind enemy lines.\n\nIf you possess knowledge of how to heal then I ask you employ it. If you do not, we have bandages to aid the wounded with. \n\nPlease help bring our people out of the fire.", objectives = "" }
WordHunterWoW_QuestEN[74571] = { title = "Clear a Path", description = "The djaradin are fortifying their beachhead. We cannot allow them to dig in any deeper or we risk their advances becoming permanent.\n\nDestroy their barricades before that can happen.", objectives = "" }
WordHunterWoW_QuestEN[74572] = { title = "Make it Rain", description = "The djaradin are setting the Plains ablaze with the reckless use of fire magic. We must act before these small sparks grow into a raging wildfire.\n\nA deep pool of fresh water can be found not far from here. Skim the surface on your drake to collect as much as you can carry, then fly over the djaradin camp to douse any flames beneath you.\n\nThis won't be enough to put out the larger blazes, but it will buy us time.", objectives = "" }
WordHunterWoW_QuestEN[74573] = { title = "Aerial Support", description = "The Primalist portals must be destroyed if we are to prevent them from infusing these raw materials with elemental energy.\n\nUnfortunately, their structures are too heavily warded for any single attack, whether mortal or draconic, to do lasting harm.\n\nTogether, though, there is a way.\n\nTake this seed. Use it to weaken their defenses and we will be able to strike before they have a chance to react.", objectives = "" }
WordHunterWoW_QuestEN[74576] = { title = "Restored Hakkari Bijou", description = "<The bijou fragments fit together with ease; drawn toward each other with minimal intervention.\n\nIt thrums gently with remnants of an ancient power. Too much to be of no consequence, yet too little to be of much use.\n\nSomeone, somewhere, would surely be interested in seeing your discovery.>", objectives = "" }
WordHunterWoW_QuestEN[74581] = { title = "The Long Knives", description = "Have you learned anything about Gor'krosh?", objectives = "" }
WordHunterWoW_QuestEN[74769] = { title = "Stemming the Irontide", description = "Unfortunately, we are not the only ones who took notice of opportunities in the Reach. \n\nOur scouts have sent word of pirate vessels moored offshore. The first longboats have apparently come ashore on our northeastern beaches.\n\nOur history is not theirs to plunder. If you come across these pirates, send them swimming back to their little boats.", objectives = "" }
WordHunterWoW_QuestEN[74771] = { title = "Key Hunting", description = "My pockets are empty. I have no more vault keys!\n\nSee if you can find any Zskera Keys, and Jeb and I will see what we can find. If we pool our keys, we can open a lot of doors.", objectives = "" }
WordHunterWoW_QuestEN[74774] = { title = "More Keys", description = "I have more keys! You can use these to open more locked doors!\n\nPlease, take these and use them within the chamber.", objectives = "" }
WordHunterWoW_QuestEN[74775] = { title = "Disciple of Fyrakk: Kretchenwrath", description = "<Fyrakk's disciple has fallen. Perhaps the remains of this beast will bring some comfort to those whose land has been ravaged.>", objectives = "" }
WordHunterWoW_QuestEN[74783] = { title = "The Sound of Silence", description = "It has been so many years since Shandaral has known true silence. With luck, our actions today will allow the echoes of this cursed place to fade.\n\nYou are due back in the Isles, no doubt--and I think it is high time I fly there as well.", objectives = "" }
WordHunterWoW_QuestEN[74786] = { title = "Snailspiration: Shimmershell Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "" }
WordHunterWoW_QuestEN[74787] = { title = "Come Snail Away", description = "Hmm. You ever mount a snail before?\n\nI've trained generations of racing snail champions, but now I've come across my toughest case yet. Problem is he's too crokin' big. Straight up barred from competition.\n\nIt's a shame to keep such a prize specimen stuck in a bucket though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", objectives = "" }
WordHunterWoW_QuestEN[74795] = { title = "An Odd Round Object", description = "<This object looked out of place in the Zskera Vaults. It is round, with three claw-like divots in it. Perhaps it is of interest to Voraxian.>", objectives = "" }
WordHunterWoW_QuestEN[74796] = { title = "A Dusty Vase", description = "<You have found a vase. It appears to represent a black dragon fighting what could be a djaradin. It could be something Voraxian is interested in.>", objectives = "" }
WordHunterWoW_QuestEN[74839] = { title = "Crystal Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74842] = { title = "Crystal Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74847] = { title = "Emberthal Awaits", description = "We are by no means ready to relax, but at least our encampment here is stable... for the time being. I should be able to handle the rest of our operation from here.\n\nEmberthal arrived while you were in the field. She and her allies are surveying the area from the cliffs above. It would be wise to check in with her, I think. We would not want her to attempt taking the Reach alone.", objectives = "" }
WordHunterWoW_QuestEN[74857] = { title = "Mouse Detective", description = "Normally I'd chase strangers off my property, but today's an exception.\n\nMy sniffin' mouse has gone missing. It's not like Persii to ignore me when I call for her...\n\nI can't smell as good as other niffen, so I can't tend to the harvest without her help.\n\nPoor thing must be so scared, out there all on her own. Please, you gotta find Persii!", objectives = "" }
WordHunterWoW_QuestEN[74858] = { title = "Agrulculture", description = "The niffen say that sniffin' mice have great noses. They can make their way through the caverns and track down the fastest racing snails. Even sniff out glow spores ready for harvest.\n\nBut I have a good nose, too. Maybe I could even sniff out those glow spores!\n\nLet's collect the harvest for the hermit. That will show him it's okay that his mouse friend isn't here--because I can fill in!", objectives = "" }
WordHunterWoW_QuestEN[74859] = { title = "Sporemoth Exterminator", description = "Looks like sporemoths are wrecking these crops.\n\nIf they keep eating all the spores, the hermit won't have anything to harvest.\n\nWe need to cull the sporemoths. That should help keep the harvest thriving--and show that I know how to take care of a farm.", objectives = "" }
WordHunterWoW_QuestEN[74860] = { title = "A Friendly Introduction", description = "It's time to deliver the harvest to the hermit. When he sees what good work we did, maybe he'll hire me as a farmhand!\n\nI, uh... tried talking to him once before. Wanted to ask if he needed a helper.\n\nDoesn't seem to like guests, though. Especially drogbar. So I got nervous and ran off.\n\nYou were looking for his mouse. Could you introduce us?", objectives = "" }
WordHunterWoW_QuestEN[74861] = { title = "An Unfriendly Confrontation", description = "I knew I recognized that drogbar's voice.\n\nHe probably took Persii. I bet he knows where she is!\n\nPlease, {name}, you gotta track down that big bully. Do whatever it takes to get Persii back!", objectives = "" }
WordHunterWoW_QuestEN[74866] = { title = "Journal Entry: Experiments", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74869] = { title = "Primordial Answers", description = "Revelations await us within this vault. Perhaps we'll find a way to protect ourselves against Primalist magic. The elementals hiding in these vaults are wild, ancient, and free of Primalist control. Perhaps they hold the secret to helping the elementals on the surface.\n\nI have an idea. We'll need four primordial cores. Then we can construct a talisman that can purify and remove the influence of Primalist control from the elementals outside.\n\nIf you help us, I will share what we have found here.", objectives = "" }
WordHunterWoW_QuestEN[74876] = { title = "The Buddy System", description = "Oh, hello there. Was I speaking my thoughts out loud again?\n\nI don't mean to trouble others with my problems, but...\n\nI'm a sniffenseeker, you see. We find unique and amazing places all over the cavern! But we have an important rule here in Loamm--we always follow the buddy system. Nobody digs alone!\n\nI've had the same buddy since we were pups, but she's too busy to dig anymore. I found this interesting new smell. Before, I had a buddy...\n\nSay, how do you feel about being a stand-in dig partner?", objectives = "" }
WordHunterWoW_QuestEN[74877] = { title = "Best Friends", description = "Really, I have fun digging with you. I do! Please, don't take this badly, but... I miss my best friend.\n\nI don't blame her for being busy. She was kidnapped, and she is the princess! I know she doesn't have lots of time. I just wish... \n\n...I don't know.\n\nMaybe I wish things were the way they used to be, when she wanted to dig with me.", objectives = "" }
WordHunterWoW_QuestEN[74878] = { title = "Old Friends, Dear Friends", description = "I don't want to give up on my best friend, but what if she doesn't want to be friends anymore?\n\nWe've been dig buddies since we were tiny pups. Maybe it matters to me more than it does to her.\n\nWhat do I even say?", objectives = "" }
WordHunterWoW_QuestEN[74880] = { title = "Journal Entry: Relics", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74882] = { title = "Crystal Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74883] = { title = "Journal Entry: The Creches", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74889] = { title = "Caldera Cruise", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74896] = { title = "Journal Entry: Silence", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74899] = { title = "Caldera Cruise - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74900] = { title = "Receiving Stone: Final Warning", description = "<This receiving stone still holds ancient words from Neltharion in an old draconic dialect.>\n\n<The dracthyr scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74901] = { title = "Sending Stone: Protest", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74902] = { title = "Sending Stone: Initial Report", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74903] = { title = "Sending Stone: The Prisoner", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "" }
WordHunterWoW_QuestEN[74908] = { title = "New Adventures", description = "Cataloger Daela is here to investigate places of wonder and mystery. Skyfox Den and Caldera of the Menders look especially promising.\n\nCompleting her quests will unlock her Envoy Tasks today. You will be able to unlock other factions' Envoy Tasks tomorrow.", objectives = "" }
WordHunterWoW_QuestEN[74909] = { title = "New Catches", description = "Turik is here to investigate the riches of the sea across the Forbidden Reach on behalf of the Iskaara Tuskarr.\n\nCompleting this quest will unlock his Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", objectives = "" }
WordHunterWoW_QuestEN[74910] = { title = "New Foes", description = "Storykeeper Ashekh is here to scout for enemies of the Maruuk.\n\nCompleting this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", objectives = "" }
WordHunterWoW_QuestEN[74911] = { title = "New Horizons", description = "Kraxxus represents the strength of Valdrakken Accord here on Forbidden Reach.\n\nCompleting this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", objectives = "" }
WordHunterWoW_QuestEN[74912] = { title = "Neltharion's Legacy", description = "<As you stare into the cracked titan gem, a voice echoes through your mind.>\n\n{name}! This is Nozdormu. \n\nThe time to redeem the legacy of your creator, Neltharion, is at hand. \n\nYou hold a vital piece to the artifact Neltharion once used to control you and all of the dracthyr.\n\nMeet me in Valdrakken. There is much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[74913] = { title = "Memories of an Artifact", description = "Emberthal aided me in discovering the Oathbinder. This was the artifact Neltharion used to control you all.\n\nI have been scouring the timeline to discover how it was made to forge a counterpart to it to protect your kind.\n\nThis gem you've recovered is just the key I need to move my studies forward.\n\nYou and I shall next meet within Zaralek Cavern, where you once fought over the broken Oathbinder.\n\nIt is there we will find the secrets to forge your own weapon to fight against tyranny.", objectives = "" }
WordHunterWoW_QuestEN[74923] = { title = "It Takes a Village to Make an Artifact", description = "You must go now and seek aid to create the key components to forge a new glove.\n\nEssence of Order is normally difficult to find, but the memories you have acquired will allow you to recover them at many locations.\n\nThis new glove will be one to empower your allies and your community... which means you will have to rely on others to aid you in this.\n\nTake the memories you've recovered and use them to teach others how to craft these parts.", objectives = "" }
WordHunterWoW_QuestEN[74924] = { title = "Nasz'uro, the Unbound Legacy", description = "Through my research, I've uncovered the last piece to make this artifact truly a counter to the Oathbinder.\n\nThe essence of Neltharion.\n\nIt is here that I can finally aid the dracthyr. We shall travel to the Maelstrom to see his final moments.\n\nWith his essence, we shall finish crafting your artifact, Nasz'uro, the Unbound Legacy.\n\nSpeak to me when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[74925] = { title = "Caldera Cruise - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74939] = { title = "Brimstone Scramble", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74942] = { title = "Grime Lies Where You're Killing Slimes", description = "Did you see that? Some of the slimes are leaving little piles of grime behind. Hmm...\n\nMelly makes stuff out of all kinds of things. You think she could use the grime to help out Tempo? I bet she could.", objectives = "" }
WordHunterWoW_QuestEN[74943] = { title = "Brimstone Scramble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74944] = { title = "Brimstone Scramble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74946] = { title = "A Place of Refuge", description = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them.\n\nThis Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. \n\nWhile her reasoning is sound, this is also the perfect location for a trap.\n\n{name}, I know you vouch for her, so I will give her the benefit of the doubt.\n\nLet us hope your trust in her is not misplaced.", objectives = "" }
WordHunterWoW_QuestEN[74948] = { title = "Snailspiration: Amethyst Softshell", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "" }
WordHunterWoW_QuestEN[74949] = { title = "Snailspiration: Archetype of Vigilance", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "" }
WordHunterWoW_QuestEN[74950] = { title = "Snailspiration: Blackchasm Crawler", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "" }
WordHunterWoW_QuestEN[74951] = { title = "Shimmering Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74952] = { title = "Snailspiration: Microlicid", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "" }
WordHunterWoW_QuestEN[74953] = { title = "The Heavy Crown", description = "I was really down when Effervesta didn't come like she said she would.\n\nBut I understand that she's so busy, what with being kidnapped and all of her duties. I don't blame her.\n\nI want to tell her how much that time meant to me when we were pups, though. That I'll be here for her if she ever needs me. Then at least she knows I'm still here.\n\nCan you help me get her attention long enough to say what I need to?", objectives = "" }
