WordHunterWoW_QuestEN[74975] = { title = "Loamm Roamm - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74977] = { title = "Loamm Roamm - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[74983] = { title = "Authentic Authorization", description = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course!\n\nIf I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans!\n\nIf you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", objectives = "" }
WordHunterWoW_QuestEN[74984] = { title = "Authentic Authorization", description = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course!\n\nIf I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans!\n\nIf you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", objectives = "" }
WordHunterWoW_QuestEN[74994] = { title = "Hraxian's Unbreakable Will", description = "", objectives = "" }
WordHunterWoW_QuestEN[74996] = { title = "A Difficult Legacy", description = "Let us talk to Veritistrasz about this vase, {name}. \n\nI want to temper your expectations though. It is just a vase, but you never know. It could be exciting.\n\nMaybe it could point us to a cache of weapons?", objectives = "" }
WordHunterWoW_QuestEN[75018] = { title = "Into the Dark", description = "My Blacktalon forces continue to secure the laboratory, but I think we are done here, {name}.\n\nWe have secured some slitherdrakes to take us down to the central platform. From there we can continue below, to where Sarkareth fell.\n\nI am certain Ebyssian and Emberthal will benefit from our presence.", objectives = "" }
WordHunterWoW_QuestEN[75023] = { title = "Memories of Sindragosa and Malygos", description = "I admit, I forgot about this phenomenon. Blue dragons who meet violent ends occasionally have some lingering arcane energy.\n\nThat energy may manifest in various ways once their essences are laid to rest. \n\nLuckily, it is a simple enough process to dispel them. Simply wave anything through the energy and it will dissipate. \n\nI shall investigate the essences of Sindragosa and Malygos within this gravestone while you handle that.", objectives = "" }
WordHunterWoW_QuestEN[75024] = { title = "Sneaky Pebbles", description = "Beetles are swarming our support creche! Some of them are now eating pieces of broken Infusers, and that's making them stronger. We keep trying to smush them, but they won't stay smushed.\n\nNow it's harder to get rid of them, but we have a plan. We've discovered that hitting them with pieces of broken Infusers can weaken them again!\n\nDo you mind helping us clear out these Infused Beetles?", objectives = "" }
WordHunterWoW_QuestEN[75025] = { title = "A Good Day for Rolling", description = "I have an... odd request for you. I need help with some squirrels. Primalists have corrupted them, and it's making them unstable!\n\nI know just the thing to cool them off. Snow! If you could roll the creatures up in a big snowball, they would cool down as the snow melts. Ingenious, yes?\n\nCan you help me?  I can't concentrate or finish my cataloguing, and I don't have time to write more eloquent prose. If nothing else, think of the loss to great literature!", objectives = "" }
WordHunterWoW_QuestEN[75026] = { title = "Up to the Highest Height!", description = "Tuskarr children sure do love kites! I've seen some of them running around with them outside Morqut Village. I've also seen a lot of those kites stuck in trees.\n\nCan you do me a favor? Could you lasso some of those kites and pull them down? They'll probably fall down in pieces, but the children can always put their kites back together. Who knows? Maybe it will teach them to be more careful.", objectives = "" }
WordHunterWoW_QuestEN[75028] = { title = "All the Broken Pieces", description = "Emberthal is in mourning. In truth, she has been grieving for Sarkareth for some time now.\n\nThe way forward is for her to determine. We can only be there to support her along the way.\n\nThere are shards of Sarkareth's signet scattered all over this room. Would you gather them? I believe she would appreciate the gesture.", objectives = "" }
WordHunterWoW_QuestEN[75029] = { title = "A Legacy, Reforged", description = "Grief is a painful burden to bear. It warms my heart to see Emberthal emerge from her sorrow and focus on her people. The pain of her loss will ebb, in due time.\n\nWe need to inform Alexstrasza and the others of what has transpired here... and of the future of the black dragonflight.\n\nWith all that you have done to ensure that we have a chance at a future, I would like you to be there.", objectives = "" }
WordHunterWoW_QuestEN[75035] = { title = "Sulfur Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75042] = { title = "Sulfur Sprint - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75043] = { title = "Sulfur Sprint - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75050] = { title = "An Eclectic Accord", description = "While the storm over the Reach was raging, I gathered allies for our eventual return. I want to ensure they have everything they need, but I can't welcome all of them personally.\n\nWould you be my envoy, {name}? Can you make sure they have what they need? We have few supplies to offer and a shortage of assistance. \n\nThe least I can do is offer my gratitude. Please thank them personally on my behalf.", objectives = "" }
WordHunterWoW_QuestEN[75065] = { title = "Campaign Testing - Dummy Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[75145] = { title = "In the Wake of the Ashes", description = "We did all we could. We will return to help them rebuild, but for now... the people of Loamm need time to mourn.\n\nAlexstrasza must be informed of what happened here today. She must be warned what has been unleashed upon the Dragon Isles.\n\nWe will meet you at the Seat of the Aspects.", objectives = "" }
WordHunterWoW_QuestEN[75148] = { title = "Ancient Techniques", description = "I've heard tales that the djaradin forge their blades with magic so hot that they can actually quench the metal with lava. Lava! It's like ice water compared to the heat their magic creates! \n\nBut I've never been able to verify it for myself. They aren't exactly peddling their wares at the market.\n\nYou smell like battle, though. Go and fetch some of their weapons for the blacksmiths back in Loamm and we'll see if the legends are true, eh?", objectives = "" }
WordHunterWoW_QuestEN[75149] = { title = "Obsidian Essays", description = "It's not common these days, but we do have a few of our histories in writing--well, carvings really. We can trace the etchings with our fingers! \n\nWe used to use clay tablets for this, but they were brittle, and prone to breaking. Not good if you want to preserve history!\n\nI hear the djaradin carve their important texts into volcanic glass. If they can manage that without shattering the tablets, we could probably learn a thing or two from their techniques!\n\nTake some samples back to Loamm for study.", objectives = "" }
WordHunterWoW_QuestEN[75150] = { title = "Incandescence", description = "Some of our incense needs to be burned very slowly to release the right aromas. You can check the heat yourself, of course--but it gets to be a bother.\n\nFortunately, I've found a solution! If you grind up shards of fire elementals and sprinkle the dust over the incense, you can keep the heat consistent using enchantments. Completely hands-free!\n\nThose shards are a bit hard to come by, though. Could you find some and bring them to my friends back in Loamm?", objectives = "" }
WordHunterWoW_QuestEN[75154] = { title = "Waygate: Morqut Islet", description = "We have access tae The Forbidden Reach now, and Cataloger Daela is already waitin' fer ya there. \n\nShe's sent me a word of a very promising spire not far from the village where she's stayin'. \n\nThink there might be another dormant Waygate around? Go on an' find out!", objectives = "" }
WordHunterWoW_QuestEN[75168] = { title = "Air Control", description = "We will never make progress while those shadowflame drakes have us pinned down from the air.\n\nGet up there and knock them from the skies.", objectives = "" }
WordHunterWoW_QuestEN[75181] = { title = "Volunteer Fire Fighters", description = "We must contain the fires these rituals are causing.\n\nWe are too far from the river to take advantage of the waters there but luckily we have two... volunteers... from beyond the plains that claim they can help. They need another pair of hands.\n\nPlease go find the goblin and gnome. I appreciate their help but they need a third party to direct them.", objectives = "" }
WordHunterWoW_QuestEN[75182] = { title = "Grand Theft Mammoth", description = "The djaradin have loaded a mammoth with the spoils of their labor here for delivery to Fyrakk.\n\nRedirect that shipment. We can make use of whatever supplies they've gathered.", objectives = "" }
WordHunterWoW_QuestEN[75189] = { title = "Safety in Numbers", description = "It is time we joined with the other survivors. The others mentioned that King Greymane and his royal guard are just south of here.", objectives = "" }
WordHunterWoW_QuestEN[75190] = { title = "Ready and Abel", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me. Someone was asking about you. A monk, Todd Abel, said he needed to speak with you. He seemed very concerned.", objectives = "" }
WordHunterWoW_QuestEN[75203] = { title = "Absent Friends", description = "I am concerned about our queen.\n\nAlexstrasza left to gather her thoughts some time ago and has not yet returned. I have no real cause for concern, but with all that has happened, I cannot help but fear for her well-being.\n\nPlease ease an old dragon's mind and ensure she is alright.", objectives = "" }
WordHunterWoW_QuestEN[75221] = { title = "Find a Rumble Coin", description = "To use this game machine, you need a Rumble Coin.\n\nThere are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later.\n\nI stashed one coin here in the Roasted Ram. If you find it, it's all yours, pal.\n\nInsert that Rumble Coin into the Rumble machine and watch the fun begin!", objectives = "" }
WordHunterWoW_QuestEN[75223] = { title = "Warcraft Rumble Minis: New Look!", description = "<You find a message etched into the foil.>\n\nThis Rumble Foil can be used at a Warcraft Rumble machine. Go and get a new look for one of your minis!", objectives = "" }
WordHunterWoW_QuestEN[75230] = { title = "Reconcilable Dissidents", description = "My hope, {name}, is that our work to understand the rebels will allow us to find a path to peace.\n\nMy concern is if we are not able to come to an understanding with Belaphon, other rebels may see her as a martyr for the cause.\n\nWhatever happens, you have my gratitude for your assistance throughout this rebellion.", objectives = "" }
WordHunterWoW_QuestEN[75232] = { title = "Fallen Effects", description = "<You wrap Sheridon's effects into a bundle, and place them in your pack to return to the camp members.>", objectives = "" }
WordHunterWoW_QuestEN[75233] = { title = "Flesh to Bone", description = "We found Skuttog near a cave to the north, by some nasty spiders. It seems like his skin is turning into bone.\n\nI can heal him, but I need venom from whatever bit him. Please help.", objectives = "" }
WordHunterWoW_QuestEN[75237] = { title = "Reach West", description = "You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? \n\nI heard the windstreams in the western Forbidden Reach are especially good today. Why don't you try a few courses out there?", objectives = "" }
WordHunterWoW_QuestEN[75239] = { title = "Disciple of Fyrakk: Shadeisethal", description = "<Fyrakk's disciple has fallen. Perhaps the remains of this beast will bring some comfort to those whose land has been ravaged.>", objectives = "" }
WordHunterWoW_QuestEN[75244] = { title = "Reunited Again", description = "Thanks to you, {name}, all of the blue dragons are accounted for. We can get back to caring for Azeroth's magic and making sure its power isn't abused.\n\nI believe a speech is in order. I would be honored if you would stay for it. \n\nWe can head to the Nexus afterwards to see what Azuregos has discovered about Sindragosa and Malygos's arcane memories.", objectives = "" }
WordHunterWoW_QuestEN[75258] = { title = "A Final Word", description = "I have sent a message to Mayla in Valdrakken, relaying what has happened here. I suspect she will be relieved to hear from me... and in knowing she was right to send you. \n\nBefore you leave, I would like to speak with you a moment.", objectives = "" }
WordHunterWoW_QuestEN[75259] = { title = "Aiding the Accord: Zskera Vaults", description = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future.\n\nNow then, to business.\n\nPathfinders of the Dragonscale Expedition are delving deeper into the Zskera Vaults on the Forbidden Reach. They are asking for brave adventurers to help them explore these new mysteries.\n\nWe await your return, {name}.", objectives = "" }
WordHunterWoW_QuestEN[75261] = { title = "Reach Center", description = "You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? \n\nI heard the windstreams in the central Forbidden Reach are especially good today. Why don't you try a few courses out there?", objectives = "" }
WordHunterWoW_QuestEN[75263] = { title = "Reach South", description = "You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? \n\nI heard the windstreams in the southern Forbidden Reach are especially good today. Why don't you try a few courses out there?", objectives = "" }
WordHunterWoW_QuestEN[75272] = { title = "Test", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75277] = { title = "Felwood Flyover", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75286] = { title = "Blacksmith's Back", description = "The kith of Loamm request the skills of a seasoned blacksmith! We've heard of the wonders you uplanders make with smelted ore!\n\nOur Kilnmaster, Mister Crubus, has heard you have devised a way to dig without claws or earth magic! What a wonderful invention!\n\nPlease deliver some of these \"shovels\" as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75288] = { title = "Enchanted Tales with Topuiz", description = "The kith of Loamm request the skills of an excellent enchanter! Magic is so prevalent in this wondrous city, it practically floats about on the breeze!\n\nOur chief Dustmonger and Sparklefinger, Mister Topuiz, has heard of the many different ways you enchant your clothes on the surface, and wishes to see some examples for himself!\n\nPlease deliver those scrolls as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75289] = { title = "Ink Master", description = "The kith of Loamm request the skills of a scribe! We niffen have heard of the powerful magical writings you produce on the surface, and wish to smell your handiwork with our own noses!\n\nOur Chief Chiseler, Miss Scridorsa, has requested a sample of both pigment and runestone be brought below.\n\nMake a delivery to Loamm as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75293] = { title = "Felwood Flyover - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75294] = { title = "Felwood Flyover - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75301] = { title = "Mistie's Mix Magic", description = "The kith of Loamm request the skills of an alchemist! We have heard tales of the wondrous concoctions you uplanders have devised!\n\nWe have alchemists of our own down below! Miss Mistie has requested a few of these items.\n\nMake a delivery to Loamm as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75304] = { title = "I Need... a Tailor", description = "The kith of Loamm request the skills of a talented tailor! We niffen are terribly curious about the magical finery you create here!\n\nWe have our own stitchers and clothes-makers down below. Mister Rossmar has expressed an interest in the procurement of bolts of high quality cloth!\n\nMake a delivery to Loamm as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75307] = { title = "Road to Season City", description = "The kith of Loamm request the skills of a culinary chef! We niffen are very proud of our cuisine, and wish to sample some from the surface!\n\nOne of our best cooks, Mister Phiary, has heard of the potent spices found in the food of the Maruuk Centaur, and the complex flavors found in the food of the Iskaara Tuskarr, and wishes to try these for himself!\n\nPlease deliver these to Loamm as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75308] = { title = "Scrybbil Engineering", description = "The kith of Loamm request the skills of an engineer! We have heard of the marvelous machines invented right here in this city, and eagerly wish to put these to use underground!\n\nWe have an engineer of our own down below, Mister Scrybbil, who has a special interest in what you call \"fishing rods\". How does such a thing work? Do you use them to spear the fish? How strange!\n\nPlease deliver these \"fishing rods\" as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75309] = { title = "If a Gem Isn't Pretty", description = "The kith of Loamm request the skills of a jewelcrafter! I have seen the wondrous sparkling gems in this glorious city, and the niffen below wish to see them as well. We don't see very well, so we know the value of a good sparkle!\n\nOur chief Gemfinder and Jewelshiner, Miss Fanilly, wishes to see some beautiful gems. I bet she'd love the ones named after Alexstrasza and Ysera!\n\nPlease deliver them to Loamm as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75310] = { title = "Winter Wander", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75311] = { title = "Winter Wander - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75312] = { title = "Winter Wander - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75317] = { title = "Nordrassil Spiral", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75318] = { title = "Nordrassil Spiral - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75319] = { title = "Nordrassil Spiral - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75330] = { title = "Hyjal Hotfoot", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75331] = { title = "Hyjal Hotfoot - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75332] = { title = "Hyjal Hotfoot - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75347] = { title = "Rocketway Ride", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75351] = { title = "Keep a Leather Eye Open", description = "The kith of Loamm request the skills of a leatherworker! We've heard of the wonders you uplanders make with hides and scales!\n\nWe have leatherworkers of our own down below! Miss Garram has heard there's a set of magical drums that make you faster! Is such a thing possible?\n\nMake a delivery to Loamm as soon as you can, won't you?", objectives = "" }
WordHunterWoW_QuestEN[75354] = { title = "Mycelium Mastery", description = "Hey there, stranger! I had an idea to run by you.\n\nThe mushrooms that grow down in Zaralek Cavern have thick and powerful mycelium capable of gripping into even the hardest crystals.\n\nImagine the possibilities with such a material! I had a friend down in Loamm who was trying to work out how to make it into a leather!\n\nInterested? Bring my friend Garram some mushrooms!", objectives = "" }
WordHunterWoW_QuestEN[75355] = { title = "Rocketway Ride - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75356] = { title = "Rocketway Ride - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75362] = { title = "Cephalo-crystalization", description = "Well, hello there!\n\nHave you seen those snails in Zaralek Cavern with the crystals growing from their shells? \n\nWhen crushed to powder and mixed with a proper solution of slime, those crystals make a paste that adds a considerable luster to our gems! Bring some to my good friend Fanilly, and I'm sure she'll be happy to chat your ear off about jewelcrafting!", objectives = "" }
WordHunterWoW_QuestEN[75363] = { title = "Deepflayer Dust", description = "Why, I just got another letter from my good friend Mistie. She's been looking for interesting ingredient ideas for her smelly concoctions!\n\nA while ago, the kithguards took down a deepflayer near Loamm. I noticed a peculiar dust it shed when it perished. It had a unique aroma to it, and I'm sure Mistie would love to experiment with something like that!\n\nCould you gather some from the deepflayers near Loamm, then bring it to Miss Mistie? You'll be doing us a favor, too!", objectives = "" }
WordHunterWoW_QuestEN[75367] = { title = "The Obsidian Rest", description = "It is a miracle this outpost survived so long after Neltharion's... disappearance. \n\nFor weeks now local scouts have reported increased djaradin activity in the area. They are amassing an army, and they are also becoming increasingly aggressive in their efforts to expand their territory.\n\nWe must take every possible precaution and try to understand our enemy's motivations.", objectives = "" }
WordHunterWoW_QuestEN[75368] = { title = "Stones and Scales", description = "I'm sure you've run into some of the mean beasties we have down in Zaralek while you were on your adventures! Have you seen any rock vipers yet? \n\nThey're covered in both scales and stones! And have massive fangs!\n\nMister Garram has offered a reward for anyone brave enough to bring him some of their hides! I'm sure he will make it worth your while!", objectives = "" }
WordHunterWoW_QuestEN[75369] = { title = "Use Your Coin!", description = "Use that coin on the Warcraft  Rumble machine over there.", objectives = "" }
WordHunterWoW_QuestEN[75371] = { title = "Fascinating Fungi", description = "Ah, Uplander! Can I ask for your assistance?\n\nThe cavern below is full of mushrooms that are useful for all kinds of things! Miss Mistie has asked for help gathering them for her alchemical experiments.\n\nShe says the Gelcap mushrooms produce sticky spores that she can make into a balm, good for easing achy joints and bunions! I sure could use some after standing around on these hard stones all day!\n\nIf you can find her some, I'm sure she will make it worth your while!", objectives = "" }
WordHunterWoW_QuestEN[75372] = { title = "Drive Them Before Us", description = "Drive these whelks from our lands, {name}!\n\nFor Imbu! For the Azure Span!", objectives = "" }
WordHunterWoW_QuestEN[75373] = { title = "Charge of the Ottuk Brigade", description = "Bah! They hide behind their barricades, hoping that will protect them from our vengeance.\n\nClear the way and we will ride them down like the cowards they are!", objectives = "" }
WordHunterWoW_QuestEN[75374] = { title = "To Defend the Span", description = "The djaradin struck without warning, {name}. Our people are capable fighters, but no one escapes a battle like this unscathed.\n\nPlease, help with the wounded. Many are trapped behind the enemy lines and can't make their way back in their current state.", objectives = "" }
WordHunterWoW_QuestEN[75375] = { title = "Burning Ice", description = "Whatever magic the djaradin are employing is lighting the ice on fire out there, {name}.\n\nWe can't let this spread to the wider Span. It has to be stopped before it consumes everything.\n\nGather as much water as you can while on that drake of yours and drown the fires. Hopefully that will be enough to extinguish them.", objectives = "" }
WordHunterWoW_QuestEN[75376] = { title = "Suffuse, Reuse, Recycle", description = "If Fyrakk is willing to openly attack the surface in pursuit of these materials, they must be vital to his plans.\n\nGrab whatever you can. There must be a way to turn these to our advantage.", objectives = "" }
WordHunterWoW_QuestEN[75377] = { title = "Maintaining the Barricade", description = "It's all I can do to keep this shield up under the barrage these shadowflame drakes are putting out.\n\nThin their ranks before we're pinned down for good.", objectives = "" }
WordHunterWoW_QuestEN[75378] = { title = "Ashenvale Ambit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75379] = { title = "Ashenvale Ambit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75380] = { title = "Ashenvale Ambit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75382] = { title = "Portal Combat", description = "The Primalists are channeling elemental forces through those portals, energizing their entire effort and speeding the production of these suffused ingots.\n\nSoon they will be stabilized enough to allow their elemental allies to pass through to reinforce their position.\n\nWe have to seal them before that happens or the battle may turn against us.\n\nTake this focus and disrupt the portals' protective runes, then we can strike from above. Only together do we stand a chance.", objectives = "" }
WordHunterWoW_QuestEN[75383] = { title = "Hideaway No More", description = "This was supposed to be a peaceful retirement, not a warzone!\n\nGrab one of those totems the shamans left lying around and put out these fires before my dreams of a nice fishing retreat go up in smoke! Literally!", objectives = "" }
WordHunterWoW_QuestEN[75384] = { title = "Payback's a Mammoth", description = "Trying to kill me I can forgive, but attacking my Hideaway? Now it's personal.\n\nThe djaradin are loading their mammoths with all the ingots they can bear to get them back to their precious Fyrakk.\n\nHijack one and bring it back here, cargo and all.", objectives = "" }
WordHunterWoW_QuestEN[75385] = { title = "Durotar Tour", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75386] = { title = "Durotar Tour - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75387] = { title = "Durotar Tour - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75388] = { title = "The Azure Vaults", description = "There's a problem in the Azure Vault, {name}. \n\nBeneath the Azure Archives rests the Azure Vault. Sindragosa stored many important and dangerous magical curiosities in it.\n\nA large group of Sundered Flame have broken into the vault to unlock its secrets.\n\nYou need to go in there and stop the Sundered Flame!", objectives = "" }
WordHunterWoW_QuestEN[75394] = { title = "Webwinder Weave", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75395] = { title = "Webwinder Weave - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75396] = { title = "Webwinder Weave - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75398] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[75407] = { title = "Silk Scavenging", description = "Hello friend! You're a tailor, right? So you must know about silk!\n\nMister Rossmar down in Loamm knows how to make special silk from the cocoons of the Underlight Moths, but could use some help gathering them up! \n\nYou should be able to find them in the mushroomy area near Glimmerogg. I'll sure he will make it worth your while!", objectives = "" }
WordHunterWoW_QuestEN[75408] = { title = "Calling All Dracthyr!", description = "<This flyer is illustrated with inviting sketches of dracthyr eating, sparring, and having fun.>\n\nCalling all dracthyr!\n\nDo you feel adrift after the events of the underground? Do you want to bond with your creche mates? Do you just need someone to talk to?\n\nCome join us at Weyrnrest for food, fun, and camaraderie! ALL dracthyr welcome!", objectives = "" }
WordHunterWoW_QuestEN[75409] = { title = "Desolace Drift", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75410] = { title = "Desolace Drift - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75411] = { title = "Desolace Drift - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75412] = { title = "Great Divide Dive", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75413] = { title = "Great Divide Dive - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75414] = { title = "Great Divide Dive - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75417] = { title = "Symbol of Hope", description = "Champion--Ebyssian, Sabellian, and Wrathion have come to an agreement of who should lead, and are presenting a unified front. All three were quite eager to speak of your contributions and aid in Zaralek Cavern as well. It seems that they are also in agreement that they could not have succeeded without you.\n\nHigh praise indeed--and well deserved.\n\nPlease, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.", objectives = "" }
WordHunterWoW_QuestEN[75419] = { title = "Sundered Flames", description = "Did Neltharion keep this place as his hoard? No wonder that Sarkareth was looking for it. \n\nNeltharion's \"treasures\" litter every corner of it.\n\nThere's no telling what Sarkareth has gotten his claws on here.\n\nStay close!", objectives = "" }
WordHunterWoW_QuestEN[75437] = { title = "Razorfen Roundabout", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75438] = { title = "Razorfen Roundabout - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75439] = { title = "Razorfen Roundabout - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75440] = { title = "Satiating Sharpbeak", description = "Sheridon Hastle was our flight master and Sharpbeak's rider. After his death, she won't let anyone touch her.\n\n<Narvra clutches her side in pain.>\n\nOr feed her. Rupert tried but... she just won't.\n\nThe rest of us are too injured to move... I'm worried about her.\n\nCan you... ow... try? Someone new may get through to her. Her feed is in the bag by the tent.\n\nAnd... if you can get her to accept food, she might let you ride her.", objectives = "" }
WordHunterWoW_QuestEN[75444] = { title = "Waygate Exploration: The Forbidden Reach", description = "<Another visit from Nanners, and another calling from the Dragonscale Expedition.\n\nIt seems Thaelin Darkanvil have something of an interest for you yet again.>", objectives = "" }
WordHunterWoW_QuestEN[75456] = { title = "News From Beneath", description = "Before I arrived, I was informed that the Life-Binder has need of our aid. There is news of the Incarnates, and she requests our presence at the Seat of the Aspects.\n\nAs for Emberthal -- there is very little we can do for now. It is best we allow her to reflect and gather thoughts alone.", objectives = "" }
WordHunterWoW_QuestEN[75458] = { title = "Three-Cheese Cake", description = "<The rat finally acknowledges your presence.>", objectives = "" }
WordHunterWoW_QuestEN[75462] = { title = "Mouse Rescuers", description = "I feel bad for everything I did working for Malrogg. He was just so big and scary, I never felt like I had a choice...\n\n<Agrul slowly shakes his head.>\n\nNo more excuses. We need to get that sniffin' mouse back home to Yarren.\n\nI was never strong enough to take on Malrogg alone. But you... You can save Persii.", objectives = "" }
WordHunterWoW_QuestEN[75463] = { title = "Thousand Needles Thread", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75464] = { title = "Thousand Needles Thread - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75465] = { title = "Thousand Needles Thread - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75466] = { title = "Lost Time-Lost Vikings", description = "Some rowdy customers stumbled out of a temporal portal a bit ago. Before I could get a Timewalker to help get them home, they decided to visit Valdrakken.\n\nWould you find Olaf, Baelog, and Eric and get them to come back here before they cause too much of a ruckus?", objectives = "" }
WordHunterWoW_QuestEN[75468] = { title = "Feralas Ruins Ramble", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75469] = { title = "Feralas Ruins Ramble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75470] = { title = "Feralas Ruins Ramble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75472] = { title = "Ahn'Qiraj Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75473] = { title = "Ahn'Qiraj Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75474] = { title = "Ahn'Qiraj Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75481] = { title = "Uldum Tour", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75482] = { title = "Uldum Tour - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75483] = { title = "Uldum Tour - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75485] = { title = "Un'Goro Crater Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75486] = { title = "Un'Goro Crater Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75487] = { title = "Un'Goro Crater Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[75493] = { title = "Surveying the Riverbed", description = "Hope you brought your boots, 'cause this is gonna be a wet one!\n\nThis river carries artifacts down from the mountains, and they wash up here in the silt. The centaur have found loads of stuff here over the years.\n\nWe're here to take a deeper look and see if there's anything interesting below the surface.", objectives = "" }
WordHunterWoW_QuestEN[75518] = { title = "The Body on the Banks", description = "<The state of the corpse of this centaur woman is surprising.\n\nHer clothing is in a style unfamiliar to you, and her skin is emblazoned with intricate tattoos.\n\nHer body is intact, so it seems as though she could not have been dead long... or could she? Conditions here may have led to better preservation.\n\nRoska will want to have a look at this!>", objectives = "" }
WordHunterWoW_QuestEN[75519] = { title = "The Long Hunt", description = "<Dori'thur hovers silently, peering at you with keen, expectant eyes.\n\nWith a taloned foot, the noble owl offers you an imbued crystal. Within that crystal, you sense a message.>", objectives = "" }
WordHunterWoW_QuestEN[75528] = { title = "A Tester's Guide to Entering Zaralek", description = "Hail, and well met!\n\nWhile the story of Zaralek has yet to unfold, there is plenty to see within the cavern! Make way to Loamm, home of the Niffen.", objectives = "" }
WordHunterWoW_QuestEN[75538] = { title = "Beginning Impositions", description = "Darkest greetings, {race}. Ahem, yes. Yes! Darkest greetings indeed.\n\n<The lanky man seems to suddenly remember where he is.>\n\nOn behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes!\n\nAhem.\n\nShe requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows...\n\n...Madam Shadow.", objectives = "" }
WordHunterWoW_QuestEN[75539] = { title = "Some Wicked Things This Way Come", description = "Phineas did well in bringing you to me, {name}. There is much work to be done.\n\nWe'd best get to it!\n\nAs a master of the dark arts, I need you to help me whip these newcomers into shape. Talk to them. They come from many walks of life--all of them unfamiliar with the dark arts.\n\nLearn their wishes. \n\nTheir hopes.\n\nTheir dreams.\n\nThis path we walk can bestow gifts unending and power unimaginable. One just needs to know what one truly desires...", objectives = "" }
WordHunterWoW_QuestEN[75540] = { title = "Hermetic Insurance", description = "Ah, the latest group have gathered beneath my wings like chicks to a mother crow. You've done well so far, {name}. They trust you. \n\nI trust you.\n\nThe next step in shepherding these simple souls along in their diabolical journeys is to safeguard them against the void. Against oblivion. Against death.\n\nTake my soulstone and use it to gird the willing... and the damned.", objectives = "" }
WordHunterWoW_QuestEN[75541] = { title = "Those Who Hesitate", description = "Hm.\n\nThere is one who has been counted amongst our number, but is not here.\n\nThe draenei.\n\n<Madam Shadow inhales.>\n\nI can taste the Light about him. Go, see to it that he rejoins us.\n\nThere is much work to be done.", objectives = "" }
WordHunterWoW_QuestEN[75542] = { title = "Curses & Cultists", description = "The wheat has been separated from the chaff. Now the fun can truly begin.\n\nI have an exciting... field trip... planned for our students. But they are not yet ready. Take my grimoire and have the pandaren, zandalari, and tauren try their hand at curses. \n\nI found some uninvited guests loitering on the edges of our fairground. They should make excellent, if unwilling, test subjects.\n\nOman will have the honor of summoning the group far afield, and I will instruct him as such.", objectives = "" }
WordHunterWoW_QuestEN[75543] = { title = "Last Rites By Accident", description = "<You can hear the faint sound of screaming coming from the other side of the portal.>", objectives = "" }
WordHunterWoW_QuestEN[75544] = { title = "When Revenge Burns Green", description = "Whatever game this Madam Shadow has been playing, it appears as though we're nearing the end of it.\n\n<Oman grunts in pain.>\n\nFrom what we've heard, it sounds like our next destination is somewhere in the Blasted Lands.  I must rest, but please {name}... go and see this through. Bring Madam Shadow to account. Avenge our fellow warlocks.", objectives = "" }
WordHunterWoW_QuestEN[75569] = { title = "Blacksmith, Black Dragon", description = "The black dragonkin in the north of Zaralek Cavern are said to be fine blacksmiths.\n\nThey're quick to claim it has something do with a \"dominion over the earth\", but I'd like to see them try burrowing like a proper niffen!\n\nStill, you can't argue with the results. Grab a few examples and bring them to Kilnmaster Crubus in Loamm so he can study their techniques.", objectives = "" }
WordHunterWoW_QuestEN[75573] = { title = "Proclamation Reclamation", description = "You know who likes to hear themselves talk, loves bureaucracy, and enchants their own records? Dragons!\n\nGo poke around in the old black dragon fort north of Loamm. I'm sure they'll be all sort of magic-ish decrees, proclamations, and shopping lists just lying around!\n\nBring whatever you uncover to Scridorsa the Chiseler back in Loamm. I'm sure she'd love something new and heavily enchanted to read!", objectives = "" }
WordHunterWoW_QuestEN[75575] = { title = "Ballistae Bits", description = "Those djaradin might smell like brutes, but their engineering corps must be top notch to keep churning out ballistae strong enough to threaten a dragon!\n\nNortheast of Loamm there's an ongoing scrap between them and some black dragons. There ought to be lots of spare parts scattered around. Or slightly used, moderately on fire ones, anyway!\n\nHaul them all back to Loamm! A little scorching won't stop our top minds from reverse niffeneering them.", objectives = "" }
WordHunterWoW_QuestEN[75598] = { title = "Snailed It", description = "Hmm. You ever mount a snail before?\n\nI've trained generations of racing snail champions, but lately I've come across my toughest case yet. Simply put, he's too crokin' big. Straight up barred from competition.\n\nIt's a shame to keep such a prize specimen stuck in a bucket, though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", objectives = "" }
WordHunterWoW_QuestEN[75600] = { title = "Silk's Silk", description = "We may not have access to all those fancy plant fibers you surface types use up here, but we do have a lot of options I bet you don't!\n\nThe spiders near Loamm make the most interesting smelling silk I ever did sniff. I think it might have something to do with their diet?\n\nIf you round some up, I'm sure Rossmar back in Loamm will be happy to teach you a thing or two about how to use it!", objectives = "" }
WordHunterWoW_QuestEN[75602] = { title = "Chips off the Old Crystal Block", description = "The crystalline creatures back home are as mysterious as they are stompy.\n\nWhat allows them to move? Are they even really alive? What do they taste like?\n\nBring Fanilly a few samples to start studying. Just not any big enough to step on anyone in Loamm, ok?", objectives = "" }
WordHunterWoW_QuestEN[75603] = { title = "Do Rites by Her", description = "This gal has been here for a long, long time. It's a wonder she's in such good condition.\n\nIt's one thing to dig up pottery shards in the mud, but something like this requires more care and expertise than you and I have combined! Maruukai isn't far from here...\n\nWe should tell the centaur about this. They can decide how best they'd like to proceed, eh?\n\nWhile we're at it, I bet some of their expert artisans can tell us about her gear.", objectives = "" }
WordHunterWoW_QuestEN[75604] = { title = "Antiquated Antics", description = "Well, there's two factors at play here, eh?\n\nWe should do our due diligence and figure out who this was a statue of. But between you and me? I'm much more interested in learning about the jokesters that turned it into this work of art.\n\nI'm sure there's a historian of the black dragonflight somewhere near Aberrus. And why don't you poke around Loamm to see if there are any stories surrounding this kind of... artistic license.", objectives = "" }
WordHunterWoW_QuestEN[75608] = { title = "Titan Trash or Titan Treasure?", description = "The watchers left all sorts of amazing technology just laying around when they went to sleep.\n\nWe could learn so much from their ancient castoffs. Even the least of contraptions are marvels to behold!\n\nIf only there was someone brave, intelligent, and dare I say handsome enough to go retrieve a few examples for our finest niffeneers back in Loamm to examine... sound familiar?", objectives = "" }
WordHunterWoW_QuestEN[75617] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[75622] = { title = "Calling All Competitors!", description = "The Artisan's Consortium has struck a deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can now purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this flier to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", objectives = "" }
WordHunterWoW_QuestEN[75625] = { title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", objectives = "" }
WordHunterWoW_QuestEN[75626] = { title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", objectives = "" }
WordHunterWoW_QuestEN[75632] = { title = "A Dislocated Disc", description = "As a gesture of good will, Eternus has pledged her assistance in finding the disc that contains Tyr's memories. The infinites have devices that can aid in divining its location.\n\nTo quote Eternus, \"This is a mess Deios made. It is fair we help clean it up.\"\n\nI feel some responsibility as well after our attempt to wake Tyr with the Silver Scale.\n\nMeet Eternus at Tyrhold. She will brief you on her progress. Perhaps now our old friend will finally join us once more.", objectives = "" }
WordHunterWoW_QuestEN[75633] = { title = "We Have the Technology", description = "During our... long discussion about how to find Tyr's disc, Chromie and I agreed that you were the right person to help us, {name}. But finding the location of Tyr's disc could be very dangerous and would likely require more than just your help.\n\nWhile I work here to narrow down what we need to find the disc, Chromie can give you more details.", objectives = "" }
WordHunterWoW_QuestEN[75634] = { title = "Reforging the Tyr's Guard", description = "After the tomb was destroyed and the Silver Scale failed to bring Tyr back, I made the decision to rededicate my life to Tyr.\n\nAnd I made the even harder decision to leave the past behind and reforge Tyr's Guard.\n\nI had faith Tyr would need me again soon. And, after consulting with the Silver Hand, Koranos and I believe we have found four worthy Tyr's Guard recruits.\n\nCome with me to Brackenhide Hollow, and assist me in their final training. Then we can venture into the timeways to find Tyr's disc.", objectives = "" }
WordHunterWoW_QuestEN[75635] = { title = "For Tyr!", description = "Did they all complete their trials successfully? Good. I'm sure you played no small part in that.\n\nThere's one final step we need to take before I can formally induct our recruits as full-fledged members of the Tyr's Guard: the Tyr's Guard initiation ceremony. \n\nIt would make me proud if you stood with us on the steps of Tyrhold as I formally reforge the Tyr's Guard. Will you join us?", objectives = "" }
WordHunterWoW_QuestEN[75636] = { title = "Tyrangulation", description = "The portals are ready. The sooner your team deploys those beacons, the sooner we can get the location of the disc. \n\nHow you deploy your forces is up to you--and Travard.", objectives = "" }
WordHunterWoW_QuestEN[75637] = { title = "The Final Beacon", description = "Valunei and Talthis still aren't back. They must have had trouble with their beacon. We can't find the disc without it, and there's no way to help from here. \n\nWe must lead the Tyr's Guard through their portal to help. Are you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[75638] = { title = "Dislocated Disc Located", description = "We were successful, {name}, but we barely made it back from our battle with the Black Empire.\n\nEternus is still divining the location of the disc, and while she does, I'd like to ask a favor.\n\nI have unwavering faith in my recruits, but...\n\nI am worried about Valunei. I would speak to her, but I don't want it to appear as though I think she has failed us. Talk to her and make sure she's all right.\n\nIt may also be a good idea to check in with the rest of Tyr's Guard as well.", objectives = "" }
WordHunterWoW_QuestEN[75639] = { title = "Fel Suspicions", description = "At the risk of stating the obvious, something very wrong is going on.\n\nI know you feel it too.\n\nMadam Shadow is sending myself and the other initiates to the Altar of Storms, to try our hand at summoning demons. Please, {name}, poke your head around here and see if you can't piece together what she's up to. \n\nI saw her and her servant heading towards the back of the faire... I'm sure she has her guard up. Maybe there's some way you can get close without drawing attention to yourself?", objectives = "" }
WordHunterWoW_QuestEN[75640] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[75643] = { title = "Orientation: Loamm Niffen", description = "I'm impressed. Elder Honeypelt speaks highly of you--and that's rare!\n\nYour friends Ebyssian and Emberthal admittedly made similar impressions with us after we caught their scent. They told me of your hunt for the fiery monster that's invaded Zaralek from the uplands. A worthy reason to become allies.\n\nBut we'll need a bit more time to discuss it. Why not take a short break to meet with my people. Trade, leisure, travel--there's no shortage of ways to spend your time here in Loamm!", objectives = "" }
WordHunterWoW_QuestEN[75644] = { title = "Six Hundred Feet Under", description = "That was just a taste of the niffen lifestyle. There's still far more to Loamm and even more from Zaralek Cavern. Continue exploring while you pursue the fiery monster, and let its scents continue to amaze you!\n\nFor now, Ebyssian asked that I send you his way. Seems your companions are planning what to do next.", objectives = "" }
WordHunterWoW_QuestEN[75645] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[75647] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[75650] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[75657] = { title = "Time-Lost Trio", description = "We have a teensy problem I could use your help with. But it's... complicated.\n\nSome time ago, King Varian Wrynn was in a gladiator trio with Broll Bearmantle and Valeera Sanguinar. Those three just showed up in this 'Field of Ferocity' place and they're not only taking on all challengers, they're beating them too! They won't return through our portals until they lose.\n\nDo you think you could find some friends and defeat them? We'll be able to convince them to go back if you can, I'm sure of it!", objectives = "" }
WordHunterWoW_QuestEN[75662] = { title = "A Race to the Finish", description = "You look like someone that enjoys a good snail race! \n\nAnd what makes a snail race good you ask? Each snail must have a chance to win! \n\nAnd sometimes the snails might need a little bit of help. \n\nIf you grab a bag of treats from the chef and toss it in their path that'll get them moving. \n\nHow about we give Bashful a nudge to victory?", objectives = "" }
WordHunterWoW_QuestEN[75665] = { title = "A Worthy Ally: Loamm Niffen", description = "Djaradin, dracthyr, and dragons! Oh my!  You can't help but smell the danger in these here caverns. We sure could use some armed assistance.\n\nYou scratch my back, and I'll make sure the kith scratch yours! We got loads of good stuff... for the right clientele.\n\nHow about it? Get out there and bury the competition?", objectives = "" }
