WordHunterWoW_QuestEN[75694] = { title = "Aberrus, the Shadowed Crucible: Sarkareth", description = "I have no interest in following my brothers within Aberrus, but I continue to care for their safety. Neltharion fell so deeply into madness that his secret stronghold is no doubt filled with any number of unspeakable dangers.\n\nGo with them, {name}. Stand with them. They will need your support in what is to come.", objectives = "" }
