WordHunterWoW_QuestEN[75985] = { title = "Rest Well, Warrior", description = "Shalkeel deserves to be seen off properly.\n\nI want to dress his burial area and say a few words. I know your time is precious, but would you take the shovel and bury his ashes while I perform the rites?", objectives = "" }
WordHunterWoW_QuestEN[75986] = { title = "Feats Per Minute", description = "Alright, one last problem to help solve. Succeed at this and we'll surely have earned an audience with Tempo!\n\nThe investigators discovered another Time Slime. A much larger, powerful Time Slime. \n\nWe've come to call it Time Slime Prime.\n\nIts temporal energies are greatly accelerated, making it especially deadly. I recommend using the metronographer several times to slow it back down before engaging in combat.", objectives = "" }
WordHunterWoW_QuestEN[75987] = { title = "Woolomancer", description = "Somehow, Jaina Proudmoore has found a magic wand. Not our Jaina, of course, but her childhood self. She is far too young to have access to such power.\n\nWe need you to help clean up the mess she's made and confiscate that wand.", objectives = "" }
WordHunterWoW_QuestEN[75988] = { title = "Lucky Hearthstone Card", description = "I was playing Hearthstone with my father when I somehow ended up here. Then some dragon whelps flew off with my lucky card to add it to their... card tornado?\n\nThen all the adults started saying I need to go home. But I can't leave without my lucky card!\n\nCan you please help me? I promise I'll go home if you bring it back for me!", objectives = "" }
WordHunterWoW_QuestEN[75989] = { title = "The Black Prince Parade", description = "Five separate portals opened up here at the same time, and the same person stepped out of each one.\n\nNow we have an inn full of Wrathions. All different ages, dealing with different things in their own lives, and very eager to blame each other for their problems.\n\nLet's get them all back to their proper times before they cause too much trouble.", objectives = "" }
WordHunterWoW_QuestEN[75990] = { title = "Star-Crossed Lovers", description = "We found a time disruption long, long ago. Someone helped Illidan charm Tyrande, dooming us all to the Burning Legion!\n\nMalfurion is so distraught he can't even sleep. He has no idea how to win her back.\n\nWe need you to help him out before the timeline is ruined.", objectives = "" }
WordHunterWoW_QuestEN[75991] = { title = "What Could Have Been", description = "A mysterious stranger showed up here a bit ago through one of those time portals. \n\nSaid there's a threat nearby they need your help with. Some kind of cloaking device. Though you might not like what you see once it's disabled.\n\nIn fact, you may not particularly like this stranger, for that matter.", objectives = "" }
WordHunterWoW_QuestEN[75998] = { title = "Crispety Crunchety", description = "<You've seen this kind of beetle near the stables in Loamm. Maybe the stable master will know more about them?>", objectives = "" }
WordHunterWoW_QuestEN[76004] = { title = "Deep Cuts", description = "<You find a discarded deepflayer claw. You've seen some niffen wield these as weapons.>", objectives = "" }
WordHunterWoW_QuestEN[76021] = { title = "Basic Kill Quest [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[76026] = { title = "Surveying the Tower", description = "Get a load of those rock formations! Surveying doesn't get much better than this.\n\nThis tower has been here for ages. The black dragonflight used it for some seriously dark stuff, but that's not why we're here. After the dragons left, a troupe of niffen bandits took shelter in the ruins and robbed the place blind. But they left a bunch of trash everywhere.\n\nImagine what we could learn about the niffen from that trash once we get digging!", objectives = "" }
WordHunterWoW_QuestEN[76030] = { title = "Airborne Winding", description = "Well hello there!\n\nWord around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over!\n\nBest,\nHarlowe Marl", objectives = "" }
WordHunterWoW_QuestEN[76032] = { title = "Hidden in the Midden", description = "<This dragon statue is similar to others found in the region but has been covered in paint.\n\nGoogly eyes, stink lines, whiskers, and all manner of other rude drawings decorate the otherwise-imposing stone. The paint looks old and is flaking in places but is not as old as the statue itself.\n\nRoska will want to have a look at this!>", objectives = "" }
