WordHunterWoW_QuestEN[76072] = { title = "Shades of Scarlet", description = "I need your help, {name}. I thought I had achieved some semblance of peace--although my sins might not be forgiven, I could at least reunite with the spirits of my beloved family. Yet...  my wife's spirit is missing. It is as though she never existed.\n\nHallow's End draws the shades that haunt the Monastery out from the shadows. Trapped in the past, they walk the grounds repeating their nightmares.\n\nWith any luck, one of them might give us answers as to what happened to her.", objectives = "" }
WordHunterWoW_QuestEN[76073] = { title = "No Laughing Matter", description = "There is a fountain terrace at the end of this path. Before the Scourge wrought havoc across Lordaeron, I used to bring Suzannah there. I remember how certain I felt then--in myself, in the Light... in her, and my children. \n\nI wonder when it was that my path started to dim.\n\nIf there is a shade that can enlighten us, they would be at the fountain.", objectives = "" }
WordHunterWoW_QuestEN[76074] = { title = "The Headless Horseman, Returned", description = "Thomas retreated into the Scarlet Monastery. His ties to this place are strong, even when he is in his corrupted form.\n\nYour name is {name}, yes? My husband trusted you to help him, and so I must ask the same. I intend to give chase, but I cannot save him alone.\n\nWill you join me?", objectives = "" }
WordHunterWoW_QuestEN[76075] = { title = "A Ghostly Message", description = "Excuse me, {name} is it? You've made quite a name for yourself lately, for both the living and the dead. \n\nI have in my possession the Tome of Thomas Thomson. For years it has been in my library, a reminder of times we must not forget. Imagine my surprise when the tome flings itself to the floor, falling open to a page with a single name on it.\n\nYours, {name}.\n\nIf Thomas' spirit is trying to reach you, then I think you should take this tome. Perhaps he awaits at the Scarlet Monastery?", objectives = "" }
WordHunterWoW_QuestEN[76076] = { title = "Small Things", description = "We had some well-meaning whelps take a few teeny objects from history. Small things can sometimes have a big impact. While the whelps are doing double chores, I need someone to return these rocks to their proper place.\n\nI know, right? Rocks? But they have to go back.", objectives = "" }
WordHunterWoW_QuestEN[76083] = { title = "Aberrus, the Shadowed Crucible: Echoes of the Earth-Warder", description = "I sense a dark presence somewhere within these halls... something strangely familiar. Perhaps it will reveal itself as we explore the many chambers of Aberrus. If you can find evidence of this looming evil, we may be able to gain easier access to the depths below.", objectives = "" }
WordHunterWoW_QuestEN[76085] = { title = "Aberrus, the Shadowed Crucible: Echoes of the Earth-Warder", description = "I sense a dark presence somewhere within these halls... something strangely familiar. Perhaps it will reveal itself as we explore the many chambers of Aberrus. If you can find evidence of this looming evil, we may be able to gain easier access to the depths below.", objectives = "" }
WordHunterWoW_QuestEN[76086] = { title = "Aberrus, the Shadowed Crucible: Echoes of the Earth-Warder", description = "I sense a dark presence somewhere within these halls... something strangely familiar. Perhaps it will reveal itself as we explore the many chambers of Aberrus. If you can find evidence of this looming evil, we may be able to gain easier access to the depths below.", objectives = "" }
WordHunterWoW_QuestEN[76101] = { title = "Tougher Down Under", description = "Quite a few uplanders have arrived since the cavern was split clean open! \n\nA friendly winged-one by the name of Vaskarn has been particularly helpful to us. She's made the guard's armor tougher and the monster hunter's weapons stronger.\n\nShe's going to be plenty valuable if you plan on taking down more giant beasties here in Zaralek!", objectives = "" }
WordHunterWoW_QuestEN[76103] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "" }
WordHunterWoW_QuestEN[76104] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "" }
